screenPanels.initJs:
function(container, apiUrl, tables) {
  let loginAttempts = 0;
  const maxAttempts = 5;
  let isAccountLocked = false;
  let currentLanguage = 'ja';

  const translations = {
    ja: {
      title: 'ハイブリッド申請承認システム',
      subtitle: 'Hybrid Application Approval System',
      userId: 'ユーザーID',
      password: 'パスワード',
      rememberMe: 'ログイン状態を保持する',
      loginButton: 'ログイン',
      forgotPassword: 'パスワードを忘れた方はこちら',
      help: 'ヘルプ・お問い合わせ',
      language: '🌐 日本語',
      userIdPlaceholder: 'ユーザーIDを入力してください',
      passwordPlaceholder: 'パスワードを入力してください'
    },
    en: {
      title: 'Hybrid Application Approval System',
      subtitle: 'ハイブリッド申請承認システム',
      userId: 'User ID',
      password: 'Password',
      rememberMe: 'Keep me logged in',
      loginButton: 'Login',
      forgotPassword: 'Forgot your password?',
      help: 'Help & Support',
      language: '🌐 English',
      userIdPlaceholder: 'Enter your user ID',
      passwordPlaceholder: 'Enter your password'
    }
  };

  // エラーメッセージ表示
  function showError(message) {
    const errorDiv = container.querySelector('#error-message');
    errorDiv.textContent = message;
    errorDiv.style.display = 'block';
  }

  // エラーメッセージ非表示
  function hideError() {
    const errorDiv = container.querySelector('#error-message');
    errorDiv.style.display = 'none';
  }

  // 言語切り替え
  function updateLanguage() {
    const t = translations[currentLanguage];

    container.querySelector('h1').textContent = t.title;
    container.querySelector('p').textContent = t.subtitle;
    container.querySelector('label[for="user-id"]').textContent = t.userId;
    container.querySelector('label[for="password"]').textContent = t.password;
    container.querySelector('label[for="remember-me"]').lastChild.textContent = ' ' + t.rememberMe;
    container.querySelector('#login-button').textContent = t.loginButton;
    container.querySelector('#forgot-password-link').textContent = t.forgotPassword;
    container.querySelector('#help-link').textContent = t.help;
    container.querySelector('#language-toggle').textContent = t.language;
    container.querySelector('#user-id').placeholder = t.userIdPlaceholder;
    container.querySelector('#password').placeholder = t.passwordPlaceholder;
  }

  // バリデーション
  function validateForm() {
    const userId = container.querySelector('#user-id').value.trim();
    const password = container.querySelector('#password').value;

    if (!userId && !password) {
      showError('ユーザーIDとパスワードを入力してください');
      return false;
    }
    if (!userId) {
      showError('ユーザーIDを入力してください');
      return false;
    }
    if (!password) {
      showError('パスワードを入力してください');
      return false;
    }
    return true;
  }

  // ログイン処理
  async function handleLogin(userId, password, rememberMe) {
    if (isAccountLocked) {
      showError('アカウントがロックされています。管理者にお問い合わせください。');
      return;
    }

    try {
      // ユーザー情報を取得
      const users = await window.aivicApi.list(0); // ユーザーテーブル
      if (!users) {
        showError('システムエラーが発生しました。しばらく後でお試しください。');
        return;
      }

      // ユーザー認証
      const user = users.find(u => 
        u.メールアドレス === userId && 
        u.アクティブフラグ === true
      );

      if (!user) {
        loginAttempts++;
        if (loginAttempts >= maxAttempts) {
          isAccountLocked = true;
          showError('パスワードを5回連続で間違えたため、アカウントがロックされました。');
        } else {
          showError('ユーザーIDまたはパスワードが正しくありません');
        }
        return;
      }

      // パスワード検証（実際の実装では暗号化されたパスワードと比較）
      if (password !== 'password123') { // 簡易実装
        loginAttempts++;
        if (loginAttempts >= maxAttempts) {
          isAccountLocked = true;
          showError('パスワードを5回連続で間違えたため、アカウントがロックされました。');
        } else {
          showError('ユーザーIDまたはパスワードが正しくありません');
        }
        return;
      }

      // ログイン成功
      loginAttempts = 0;
      hideError();

      // 最終ログイン日時を更新
      await window.aivicApi.update(0, user.ユーザーID, {
        最終ログイン日時: new Date().toISOString()
      });

      // ログイン状態保持
      if (rememberMe) {
        localStorage.setItem('loginState', JSON.stringify({
          userId: user.ユーザーID,
          userName: user.ユーザー名,
          loginTime: new Date().toISOString()
        }));
      }

      // セッション設定
      sessionStorage.setItem('currentUser', JSON.stringify(user));

      // ダッシュボードに遷移
      window.showScreen("scr-1779422326698"); // 申請書類作成画面をホームとして使用

    } catch (error) {
      console.error('Login error:', error);
      showError('ログイン処理中にエラーが発生しました');
    }
  }

  // パスワード表示切り替え
  container.querySelector('#toggle-password').addEventListener('click', () => {
    const passwordInput = container.querySelector('#password');
    const toggleBtn = container.querySelector('#toggle-password');

    if (passwordInput.type === 'password') {
      passwordInput.type = 'text';
      toggleBtn.textContent = '🙈';
    } else {
      passwordInput.type = 'password';
      toggleBtn.textContent = '👁️';
    }
  });

  // ログインフォーム送信
  container.querySelector('#login-form').addEventListener('submit', async (e) => {
    e.preventDefault();

    if (!validateForm()) return;

    const userId = container.querySelector('#user-id').value.trim();
    const password = container.querySelector('#password').value;
    const rememberMe = container.querySelector('#remember-me').checked;

    await handleLogin(userId, password, rememberMe);
  });

  // 言語切り替え
  container.querySelector('#language-toggle').addEventListener('click', () => {
    currentLanguage = currentLanguage === 'ja' ? 'en' : 'ja';
    updateLanguage();
  });

  // パスワード忘れリンク
  container.querySelector('#forgot-password-link').addEventListener('click', (e) => {
    e.preventDefault();
    // パスワードリセット画面に遷移（実装時は適切な画面IDに変更）
    alert('パスワードリセット機能は準備中です。管理者にお問い合わせください。');
  });

  // ヘルプリンク
  container.querySelector('#help-link').addEventListener('click', (e) => {
    e.preventDefault();
    // ヘルプページに遷移
    window.open('/help', '_blank');
  });

  // ログインボタンのホバー効果
  const loginBtn = container.querySelector('#login-button');
  loginBtn.addEventListener('mouseenter', () => {
    loginBtn.style.background = 'var(--primary-hover)';
  });
  loginBtn.addEventListener('mouseleave', () => {
    loginBtn.style.background = 'var(--primary)';
  });

  // フォーカス効果
  const inputs = container.querySelectorAll('input[type="text"], input[type="password"]');
  inputs.forEach(input => {
    input.addEventListener('focus', () => {
      input.style.outline = 'none';
      input.style.borderColor = 'var(--primary)';
      input.style.boxShadow = '0 0 0 2px rgba(255,255,255,0.08)';
    });
    input.addEventListener('blur', () => {
      input.style.borderColor = 'rgba(255,255,255,0.18)';
      input.style.boxShadow = 'none';
    });
  });

  // 保存されたログイン状態をチェック
  const savedLogin = localStorage.getItem('loginState');
  if (savedLogin) {
    try {
      const loginData = JSON.parse(savedLogin);
      const loginTime = new Date(loginData.loginTime);
      const now = new Date();
      const hoursDiff = (now - loginTime) / (1000 * 60 * 60);

      // 24時間以内なら自動ログイン
      if (hoursDiff < 24) {
        container.querySelector('#user-id').value = loginData.userId;
        container.querySelector('#remember-me').checked = true;
      } else {
        localStorage.removeItem('loginState');
      }
    } catch (error) {
      localStorage.removeItem('loginState');
    }
  }

  // 初期言語設定
  updateLanguage();
}

function(container, apiUrl, tables) {
  let uploadedFiles = [];
  let currentDetectionResult = null;

  // DOM要素の取得
  const dropZone = container.querySelector('#drop-zone');
  const fileInput = container.querySelector('#file-input');
  const uploadProgress = container.querySelector('#upload-progress');
  const progressBar = container.querySelector('#progress-bar');
  const uploadedFilesContainer = container.querySelector('#uploaded-files');
  const detectionResult = container.querySelector('#detection-result');
  const detectedType = container.querySelector('#detected-type');
  const confidenceBar = container.querySelector('#confidence-fill');
  const confidenceText = container.querySelector('#confidence-text');
  const lowConfidenceWarning = container.querySelector('#low-confidence-warning');
  const manualDocumentType = container.querySelector('#manual-document-type');
  const applicationTitle = container.querySelector('#application-title');
  const applicationDescription = container.querySelector('#application-description');
  const approverList = container.querySelector('#approver-list');
  const approverSteps = container.querySelector('#approver-steps');
  const errorMessage = container.querySelector('#error-message');
  const errorText = container.querySelector('#error-text');

  // ファイルアップロード関連
  container.querySelector('#btn-file-select').addEventListener('click', () => {
    fileInput.click();
  });

  dropZone.addEventListener('click', () => {
    fileInput.click();
  });

  dropZone.addEventListener('dragover', (e) => {
    e.preventDefault();
    dropZone.style.borderColor = 'var(--primary)';
    dropZone.style.background = 'rgba(0,0,0,0.25)';
  });

  dropZone.addEventListener('dragleave', (e) => {
    e.preventDefault();
    dropZone.style.borderColor = 'rgba(255,255,255,0.18)';
    dropZone.style.background = 'rgba(0,0,0,0.15)';
  });

  dropZone.addEventListener('drop', (e) => {
    e.preventDefault();
    dropZone.style.borderColor = 'rgba(255,255,255,0.18)';
    dropZone.style.background = 'rgba(0,0,0,0.15)';

    const files = Array.from(e.dataTransfer.files);
    handleFileUpload(files);
  });

  fileInput.addEventListener('change', (e) => {
    const files = Array.from(e.target.files);
    handleFileUpload(files);
  });

  // ファイルアップロード処理
  function handleFileUpload(files) {
    hideError();

    // ファイル形式チェック
    const allowedTypes = ['application/pdf', 'image/jpeg', 'image/jpg', 'image/png'];
    const maxSize = 10 * 1024 * 1024; // 10MB

    for (const file of files) {
      if (!allowedTypes.includes(file.type)) {
        showError(`対応していないファイル形式です: ${file.name}\nPDF、JPEG、PNG形式のファイルをアップロードしてください。`);
        return;
      }

      if (file.size > maxSize) {
        showError(`ファイルサイズが上限を超過しています: ${file.name}\n最大10MBまでのファイルをアップロードしてください。`);
        return;
      }
    }

    // アップロード処理開始
    uploadProgress.style.display = 'block';
    let progress = 0;

    const uploadInterval = setInterval(() => {
      progress += Math.random() * 20;
      if (progress >= 100) {
        progress = 100;
        clearInterval(uploadInterval);

        // アップロード完了
        setTimeout(() => {
          uploadProgress.style.display = 'none';
          progressBar.style.width = '0%';

          // ファイルを追加
          files.forEach(file => {
            uploadedFiles.push({
              id: Date.now() + Math.random(),
              name: file.name,
              size: file.size,
              type: file.type
            });
          });

          renderUploadedFiles();
          performAutoDetection();
        }, 500);
      }
      progressBar.style.width = progress + '%';
    }, 100);
  }

  // アップロード済みファイル表示
  function renderUploadedFiles() {
    if (uploadedFiles.length === 0) {
      uploadedFilesContainer.innerHTML = '';
      return;
    }

    uploadedFilesContainer.innerHTML = `
      <div style="margin-top: 12px;">
        <div style="font-size: 12px; color: var(--text); margin-bottom: 8px; font-weight: 500;">アップロード済みファイル:</div>
        ${uploadedFiles.map(file => `
          <div style="display: flex; justify-content: space-between; align-items: center; padding: 6px 10px; background: rgba(0,0,0,0.15); border-radius: 4px; margin-bottom: 4px;">
            <div>
              <div style="font-size: 13px; color: var(--text);">${file.name}</div>
              <div style="font-size: 11px; color: var(--text-muted);">${formatFileSize(file.size)}</div>
            </div>
            <button class="action-btn secondary" onclick="removeFile('${file.id}')" style="padding: 4px 8px; font-size: 11px;">削除</button>
          </div>
        `).join('')}
      </div>
    `;
  }

  // ファイル削除
  window.removeFile = function(fileId) {
    uploadedFiles = uploadedFiles.filter(f => f.id !== fileId);
    renderUploadedFiles();

    if (uploadedFiles.length === 0) {
      detectionResult.style.display = 'none';
      currentDetectionResult = null;
      updateApprovalFlow();
    }
  };

  // ファイルサイズフォーマット
  function formatFileSize(bytes) {
    if (bytes === 0) return '0 Bytes';
    const k = 1024;
    const sizes = ['Bytes', 'KB', 'MB', 'GB'];
    const i = Math.floor(Math.log(bytes) / Math.log(k));
    return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + ' ' + sizes[i];
  }

  // 自動判別処理
  function performAutoDetection() {
    if (uploadedFiles.length === 0) return;

    // 模擬的な自動判別処理
    setTimeout(() => {
      const documentTypes = [
        { code: 'vacation-request', name: '休暇申請書', confidence: 0.92 },
        { code: 'expense-report', name: '経費申請書', confidence: 0.88 },
        { code: 'business-proposal', name: '稟議書', confidence: 0.85 },
        { code: 'purchase-request', name: '購入申請書', confidence: 0.79 },
        { code: 'overtime-request', name: '残業申請書', confidence: 0.45 }
      ];

      const randomType = documentTypes[Math.floor(Math.random() * documentTypes.length)];

      currentDetectionResult = {
        type: randomType.code,
        typeName: randomType.name,
        confidence: randomType.confidence
      };

      // 判別結果表示
      detectionResult.style.display = 'block';
      detectedType.textContent = randomType.name;
      confidenceBar.style.width = (randomType.confidence * 100) + '%';
      confidenceText.textContent = Math.round(randomType.confidence * 100) + '%';

      // 信頼度が低い場合の警告
      if (randomType.confidence < 0.7) {
        lowConfidenceWarning.style.display = 'block';
      } else {
        lowConfidenceWarning.style.display = 'none';
      }

      // 手動選択を自動判別結果に設定
      manualDocumentType.value = randomType.code;

      updateApprovalFlow();
    }, 1500);
  }

  // 承認フロー更新
  function updateApprovalFlow() {
    const selectedType = manualDocumentType.value;
    const urgency = container.querySelector('input[name="urgency"]:checked')?.value || 'normal';

    if (!selectedType) {
      approverList.style.display = 'none';
      return;
    }

    // 承認フロー設定（文書種別と緊急度に基づく）
    const approvalFlows = {
      'vacation-request': {
        normal: [
          { step: 1, name: '直属上司', role: '課長' },
          { step: 2, name: '部門長', role: '部長' }
        ],
        urgent: [
          { step: 1, name: '部門長', role: '部長' }
        ]
      },
      'expense-report': {
        normal: [
          { step: 1, name: '直属上司', role: '課長' },
          { step: 2, name: '経理担当', role: '経理課長' },
          { step: 3, name: '部門長', role: '部長' }
        ],
        urgent: [
          { step: 1, name: '直属上司', role: '課長' },
          { step: 2, name: '部門長', role: '部長' }
        ]
      },
      'business-proposal': {
        normal: [
          { step: 1, name: '直属上司', role: '課長' },
          { step: 2, name: '部門長', role: '部長' },
          { step: 3, name: '役員', role: '取締役' }
        ],
        urgent: [
          { step: 1, name: '部門長', role: '部長' },
          { step: 2, name: '役員', role: '取締役' }
        ]
      },
      'purchase-request': {
        normal: [
          { step: 1, name: '直属上司', role: '課長' },
          { step: 2, name: '購買担当', role: '購買課長' }
        ],
        urgent: [
          { step: 1, name: '購買担当', role: '購買課長' }
        ]
      },
      'overtime-request': {
        normal: [
          { step: 1, name: '直属上司', role: '課長' }
        ],
        urgent: [
          { step: 1, name: '直属上司', role: '課長' }
        ]
      },
      'travel-request': {
        normal: [
          { step: 1, name: '直属上司', role: '課長' },
          { step: 2, name: '総務担当', role: '総務課長' }
        ],
        urgent: [
          { step: 1, name: '直属上司', role: '課長' }
        ]
      }
    };

    const flow = approvalFlows[selectedType]?.[urgency] || [];

    if (flow.length > 0) {
      approverList.style.display = 'block';
      approverSteps.innerHTML = flow.map(approver => `
        <div style="display: flex; align-items: center; padding: 6px 10px; background: rgba(0,0,0,0.15); border-radius: 4px; margin-bottom: 4px;">
          <div style="width: 24px; height: 24px; background: var(--primary); color: #fff; border-radius: 50%; display: flex; align-items: center; justify-content: center; font-size: 11px; font-weight: 500; margin-right: 8px;">
            ${approver.step}
          </div>
          <div>
            <div style="font-size: 13px; color: var(--text);">${approver.name}</div>
            <div style="font-size: 11px; color: var(--text-muted);">${approver.role}</div>
          </div>
        </div>
      `).join('');
    } else {
      approverList.style.display = 'none';
    }
  }

  // 手動文書種別変更時の承認フロー更新
  manualDocumentType.addEventListener('change', updateApprovalFlow);

  // 緊急度変更時の承認フロー更新
  container.addEventListener('change', (e) => {
    if (e.target.name === 'urgency') {
      updateApprovalFlow();
    }
  });

  // エラー表示/非表示
  function showError(message) {
    errorText.textContent = message;
    errorMessage.style.display = 'block';
  }

  function hideError() {
    errorMessage.style.display = 'none';
  }

  // バリデーション
  function validateForm() {
    const title = applicationTitle.value.trim();

    if (!title) {
      showError('申請タイトルは必須項目です。');
      applicationTitle.focus();
      return false;
    }

    if (uploadedFiles.length === 0) {
      showError('申請書類をアップロードしてください。');
      return false;
    }

    const selectedType = manualDocumentType.value;
    if (!selectedType) {
      showError('文書種別を選択してください。');
      manualDocumentType.focus();
      return false;
    }

    return true;
  }

  // 申請登録
  container.querySelector('#btn-register').addEventListener('click', async () => {
    hideError();

    if (!validateForm()) {
      return;
    }

    const urgency = container.querySelector('input[name="urgency"]:checked')?.value || 'normal';

    const applicationData = {
      申請者ID: 'current-user-id', // 実際の実装では現在のユーザーIDを使用
      申請種別: manualDocumentType.value,
      申請タイトル: applicationTitle.value.trim(),
      申請内容: applicationDescription.value.trim(),
      承認状態: '申請中',
      承認段階: 1,
      緊急フラグ: urgency === 'urgent',
      添付ファイル有無: uploadedFiles.length > 0,
      作成者ID: 'current-user-id'
    };

    try {
      const saved = await window.aivicApi.save(1, applicationData); // 申請書類テーブル

      if (saved) {
        // 成功メッセージ
        alert('申請書類が正常に登録されました。\n申請ID: ' + saved.id);

        // フォームクリア
        clearForm();
      } else {
        showError('申請書類の登録に失敗しました。');
      }
    } catch (error) {
      showError('申請書類の登録中にエラーが発生しました。');
    }
  });

  // クリア処理
  function clearForm() {
    uploadedFiles = [];
    currentDetectionResult = null;

    renderUploadedFiles();
    detectionResult.style.display = 'none';
    approverList.style.display = 'none';

    applicationTitle.value = '';
    applicationDescription.value = '';
    manualDocumentType.value = '';
    container.querySelector('input[name="urgency"][value="normal"]').checked = true;

    hideError();
  }

  container.querySelector('#btn-clear').addEventListener('click', () => {
    if (confirm('入力内容をクリアしますか？')) {
      clearForm();
    }
  });

  // 文書種別判定画面への遷移
  container.querySelector('#btn-document-detection').addEventListener('click', () => {
    window.showScreen("scr-1779422563059");
  });

  // 初期化
  updateApprovalFlow();
}

function(container, apiUrl, tables) {
  let currentData = [];
  let sortColumn = null;
  let sortDirection = 'asc';

  // ユーザー情報をマップ化
  const usersMap = {};
  if (tables[0]) {
    tables[0].records.forEach(user => {
      usersMap[user.ユーザーID] = user.ユーザー名;
    });
  }

  // 処理ルート情報をマップ化
  const routesMap = {};
  if (tables[7]) {
    tables[7].records.forEach(route => {
      routesMap[route.申請書類ID] = route;
    });
  }

  // 承認ステップ情報をマップ化
  const stepsMap = {};
  if (tables[4]) {
    tables[4].records.forEach(step => {
      if (!stepsMap[step.申請書類ID]) {
        stepsMap[step.申請書類ID] = [];
      }
      stepsMap[step.申請書類ID].push(step);
    });
  }

  // 優先度ラベル
  const priorityLabels = {
    1: { label: '低', color: '#6b7280' },
    2: { label: '通常', color: '#3b82f6' },
    3: { label: '高', color: '#f59e0b' },
    4: { label: '緊急', color: '#ef4444' }
  };

  // 承認状態の色分け
  const statusColors = {
    '申請中': '#6b7280',
    '承認待ち': '#f59e0b',
    '承認済': '#10b981',
    '却下': '#ef4444',
    '取下げ': '#6b7280'
  };

  // 遅延日数計算
  function calculateDelayDays(createdDate, status) {
    if (status === '承認済' || status === '却下' || status === '取下げ') {
      return 0;
    }
    const created = new Date(createdDate);
    const now = new Date();
    const diffTime = now - created;
    const diffDays = Math.floor(diffTime / (1000 * 60 * 60 * 24));
    return Math.max(0, diffDays - 3); // 3日以内は遅延なし
  }

  // 進捗バー生成
  function createProgressBar(applicationId) {
    const steps = stepsMap[applicationId] || [];
    if (steps.length === 0) return '<div style="font-size: 11px; color: var(--text-muted);">-</div>';

    const completedSteps = steps.filter(s => s.承認状態 === '承認済').length;
    const totalSteps = steps.length;
    const progress = totalSteps > 0 ? Math.round((completedSteps / totalSteps) * 100) : 0;

    return `
      <div style="display: flex; align-items: center; gap: 6px;">
        <div style="width: 60px; height: 6px; background: rgba(255,255,255,0.1); border-radius: 3px; overflow: hidden;">
          <div style="width: ${progress}%; height: 100%; background: var(--primary); transition: width 0.3s;"></div>
        </div>
        <span style="font-size: 11px; color: var(--text-muted);">${progress}%</span>
      </div>
    `;
  }

  // テーブル再描画
  function renderRows(rows) {
    const tbody = container.querySelector('#applications-tbody');
    const resultCount = container.querySelector('#result-count');

    if (!rows || rows.length === 0) {
      tbody.innerHTML = '<tr><td colspan="10" style="text-align: center; padding: 20px; color: var(--text-muted);">該当するデータがありません</td></tr>';
      resultCount.textContent = '0件';
      return;
    }

    tbody.innerHTML = rows.map(row => {
      const route = routesMap[row.申請書類ID];
      const currentApprover = route ? usersMap[route.現在承認者ID] || '-' : '-';
      const delayDays = calculateDelayDays(row.作成日時, row.承認状態);
      const isDelayed = delayDays > 0;
      const priority = priorityLabels[route?.優先度 || 2];

      return `
        <tr data-id="${row.申請書類ID}" style="${isDelayed ? 'background: rgba(239, 68, 68, 0.05); border-left: 3px solid #ef4444;' : ''}">
          <td style="padding: 6px 10px; font-size: 13px;">${row.申請種別 || ''}</td>
          <td style="padding: 6px 10px; font-size: 13px;">
            <a href="#" class="detail-link" data-id="${row.申請書類ID}" style="color: var(--primary); text-decoration: none; cursor: pointer;">
              ${row.申請タイトル || ''}
            </a>
          </td>
          <td style="padding: 6px 10px; font-size: 13px;">${usersMap[row.申請者ID] || ''}</td>
          <td style="padding: 6px 10px; font-size: 13px;">${row.作成日時 ? new Date(row.作成日時).toLocaleDateString('ja-JP') : ''}</td>
          <td style="padding: 6px 10px; font-size: 13px;">
            <span style="padding: 2px 6px; border-radius: 4px; font-size: 11px; background: ${statusColors[row.承認状態] || '#6b7280'}20; color: ${statusColors[row.承認状態] || '#6b7280'}; border: 1px solid ${statusColors[row.承認状態] || '#6b7280'}40;">
              ${row.承認状態 || ''}
            </span>
          </td>
          <td style="padding: 6px 10px; font-size: 13px;">${currentApprover}</td>
          <td style="padding: 6px 10px;">${createProgressBar(row.申請書類ID)}</td>
          <td style="padding: 6px 10px; font-size: 13px;">
            <span style="padding: 2px 6px; border-radius: 4px; font-size: 11px; background: ${priority.color}20; color: ${priority.color}; border: 1px solid ${priority.color}40;">
              ${priority.label}
            </span>
          </td>
          <td style="padding: 6px 10px; font-size: 13px; ${isDelayed ? 'color: #ef4444; font-weight: 600;' : 'color: var(--text-muted);'}">
            ${delayDays > 0 ? `${delayDays}日` : '-'}
            ${isDelayed ? ' ⚠️' : ''}
          </td>
          <td style="padding: 6px 10px;">
            <button class="action-btn secondary detail-btn" data-id="${row.申請書類ID}" style="font-size: 11px; padding: 4px 8px;">詳細</button>
          </td>
        </tr>
      `;
    }).join('');

    resultCount.textContent = `${rows.length}件`;
  }

  // 検索・フィルター処理
  function performSearch() {
    const documentType = container.querySelector('#filter-document-type').value;
    const approvalStatus = container.querySelector('#filter-approval-status').value;
    const applicantName = container.querySelector('#search-applicant').value.trim();
    const approverName = container.querySelector('#search-approver').value.trim();
    const startDate = container.querySelector('#search-start-date').value;
    const endDate = container.querySelector('#search-end-date').value;
    const errorDiv = container.querySelector('#error-message');

    // 日付バリデーション
    if (startDate && endDate && new Date(startDate) > new Date(endDate)) {
      errorDiv.textContent = '開始日は終了日より前の日付を入力してください';
      errorDiv.style.display = 'block';
      return;
    }

    // 特殊文字チェック
    const specialCharPattern = /<[^>]*>|[<>\"'&]/;
    if (specialCharPattern.test(applicantName) || specialCharPattern.test(approverName)) {
      errorDiv.textContent = '検索条件に無効な文字が含まれています';
      errorDiv.style.display = 'block';
      return;
    }

    errorDiv.style.display = 'none';

    window.aivicApi.list(1).then(rows => {
      if (!rows) return;

      let filtered = rows.filter(row => {
        // 文書種別フィルター
        if (documentType && row.申請種別 !== documentType) return false;

        // 承認状況フィルター
        if (approvalStatus && row.承認状態 !== approvalStatus) return false;

        // 申請者名検索
        if (applicantName) {
          const applicant = usersMap[row.申請者ID] || '';
          if (!applicant.includes(applicantName)) return false;
        }

        // 承認者名検索
        if (approverName) {
          const route = routesMap[row.申請書類ID];
          const currentApprover = route ? usersMap[route.現在承認者ID] || '' : '';
          if (!currentApprover.includes(approverName)) return false;
        }

        // 申請日期間検索
        if (startDate || endDate) {
          const applicationDate = new Date(row.作成日時);
          if (startDate && applicationDate < new Date(startDate)) return false;
          if (endDate && applicationDate > new Date(endDate + ' 23:59:59')) return false;
        }

        return true;
      });

      currentData = filtered;
      renderRows(filtered);
    });
  }

  // ソート処理
  function sortData(column) {
    if (sortColumn === column) {
      sortDirection = sortDirection === 'asc' ? 'desc' : 'asc';
    } else {
      sortColumn = column;
      sortDirection = 'asc';
    }

    const sorted = [...currentData].sort((a, b) => {
      let aVal, bVal;

      if (column === '申請種別') {
        aVal = a.申請種別 || '';
        bVal = b.申請種別 || '';
      } else if (column === '優先度') {
        const aRoute = routesMap[a.申請書類ID];
        const bRoute = routesMap[b.申請書類ID];
        aVal = aRoute?.優先度 || 2;
        bVal = bRoute?.優先度 || 2;
      }

      if (typeof aVal === 'number') {
        return sortDirection === 'asc' ? aVal - bVal : bVal - aVal;
      } else {
        return sortDirection === 'asc' ? aVal.localeCompare(bVal) : bVal.localeCompare(aVal);
      }
    });

    renderRows(sorted);
  }

  // CSVエクスポート
  function exportCSV() {
    window.aivicApi.list(1).then(rows => {
      if (!rows || rows.length === 0) {
        alert('エクスポートするデータがありません');
        return;
      }

      const headers = ['申請種別', '申請タイトル', '申請者', '申請日', '承認状態', '現在承認者', '優先度', '遅延日数'];
      const csvData = rows.map(row => {
        const route = routesMap[row.申請書類ID];
        const currentApprover = route ? usersMap[route.現在承認者ID] || '' : '';
        const delayDays = calculateDelayDays(row.作成日時, row.承認状態);
        const priority = priorityLabels[route?.優先度 || 2];

        return [
          row.申請種別 || '',
          row.申請タイトル || '',
          usersMap[row.申請者ID] || '',
          row.作成日時 ? new Date(row.作成日時).toLocaleDateString('ja-JP') : '',
          row.承認状態 || '',
          currentApprover,
          priority.label,
          delayDays > 0 ? `${delayDays}日` : ''
        ].map(field => `"${String(field).replace(/"/g, '""')}"`).join(',');
      });

      const csv = '\uFEFF' + [headers.join(','), ...csvData].join('\n');
      const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
      const link = document.createElement('a');
      link.href = URL.createObjectURL(blob);
      link.download = `承認フロー進捗_${new Date().toISOString().split('T')[0]}.csv`;
      link.click();
    });
  }

  // 初期データ読み込み
  window.aivicApi.list(1).then(rows => {
    currentData = rows || [];
    renderRows(currentData);
  });

  // イベントリスナー
  container.querySelector('#btn-search').addEventListener('click', performSearch);

  container.querySelector('#btn-clear').addEventListener('click', () => {
    container.querySelector('#filter-document-type').value = '';
    container.querySelector('#filter-approval-status').value = '';
    container.querySelector('#search-applicant').value = '';
    container.querySelector('#search-approver').value = '';
    container.querySelector('#search-start-date').value = '';
    container.querySelector('#search-end-date').value = '';
    container.querySelector('#error-message').style.display = 'none';

    window.aivicApi.list(1).then(rows => {
      currentData = rows || [];
      renderRows(currentData);
    });
  });

  container.querySelector('#btn-csv-export').addEventListener('click', exportCSV);

  container.querySelector('#btn-delay-check').addEventListener('click', () => {
    window.showScreen("scr-1779422271790");
  });

  container.querySelector('#btn-route-change').addEventListener('click', () => {
    window.showScreen("scr-1779422283293");
  });

  // ソートイベント
  container.addEventListener('click', (e) => {
    const sortHeader = e.target.closest('[data-sort]');
    if (sortHeader) {
      sortData(sortHeader.dataset.sort);
    }
  });

  // 詳細画面遷移
  container.addEventListener('click', (e) => {
    const detailBtn = e.target.closest('.detail-btn, .detail-link');
    if (detailBtn) {
      e.preventDefault();
      window.showScreen("scr-1779422369173");
    }
  });
}

function(container, apiUrl, tables) {
  // データ構造のマッピング
  const applicationTable = tables.find(t => t.tableName === '申請書類') || tables[1];
  const approvalFlowTable = tables.find(t => t.tableName === '承認フロー定義') || tables[3];
  const approvalStepTable = tables.find(t => t.tableName === '承認ステップ') || tables[4];
  const userTable = tables.find(t => t.tableName === 'ユーザー') || tables[0];
  const routeTable = tables.find(t => t.tableName === '処理ルート') || tables[7];
  const notificationTable = tables.find(t => t.tableName === '通知履歴') || tables[6];

  let currentApplication = null;
  let currentRoute = null;

  // DOM要素の取得
  const applicationSelect = container.querySelector('#application-select');
  const newRouteSelect = container.querySelector('#new-route-select');
  const currentRouteDisplay = container.querySelector('#current-route-display');
  const approvalStepsTbody = container.querySelector('#approval-steps-tbody');
  const changeReasonTextarea = container.querySelector('#change-reason');
  const notificationMessageTextarea = container.querySelector('#notification-message');
  const reasonCharCount = container.querySelector('#reason-char-count');
  const messageCharCount = container.querySelector('#message-char-count');
  const errorMessage = container.querySelector('#error-message');
  const confirmationModal = container.querySelector('#confirmation-modal');
  const confirmationContent = container.querySelector('#confirmation-content');

  // 文字数カウント機能
  changeReasonTextarea.addEventListener('input', () => {
    const count = changeReasonTextarea.value.length;
    reasonCharCount.textContent = count;
    if (count > 500) {
      changeReasonTextarea.value = changeReasonTextarea.value.substring(0, 500);
      reasonCharCount.textContent = 500;
    }
  });

  notificationMessageTextarea.addEventListener('input', () => {
    const count = notificationMessageTextarea.value.length;
    messageCharCount.textContent = count;
    if (count > 1000) {
      notificationMessageTextarea.value = notificationMessageTextarea.value.substring(0, 1000);
      messageCharCount.textContent = 1000;
    }
  });

  // 申請書類データの読み込み
  async function loadApplications() {
    const applications = await window.aivicApi.list(tables.indexOf(applicationTable));
    if (applications) {
      applicationSelect.innerHTML = '<option value="">選択してください</option>';
      applications.forEach(app => {
        const option = document.createElement('option');
        option.value = app.id;
        option.textContent = `${app.申請種別} - ${app.申請タイトル}`;
        applicationSelect.appendChild(option);
      });
    }
  }

  // 処理ルートデータの読み込み
  async function loadRoutes() {
    const flows = await window.aivicApi.list(tables.indexOf(approvalFlowTable));
    if (flows) {
      newRouteSelect.innerHTML = '<option value="">選択してください</option>';
      flows.forEach(flow => {
        const option = document.createElement('option');
        option.value = flow.id;
        option.textContent = flow.承認フロー名;
        newRouteSelect.appendChild(option);
      });
    }
  }

  // 現在の処理ルート表示
  async function displayCurrentRoute(applicationId) {
    const routes = await window.aivicApi.list(tables.indexOf(routeTable));
    const applications = await window.aivicApi.list(tables.indexOf(applicationTable));

    if (routes && applications) {
      const route = routes.find(r => r.申請書類ID === applicationId);
      const application = applications.find(a => a.id === applicationId);

      if (route && application) {
        currentRoute = route;
        currentApplication = application;

        currentRouteDisplay.innerHTML = `
          <div style="font-size: 12px; color: var(--text);">
            <div><strong>申請種別:</strong> ${application.申請種別}</div>
            <div><strong>申請者:</strong> ${application.申請者ID}</div>
            <div><strong>現在の状況:</strong> ${route.処理状況}</div>
            <div><strong>現在のステップ:</strong> ${route.現在ステップ番号}</div>
          </div>
        `;

        await loadApprovalSteps(applicationId);
      } else {
        currentRouteDisplay.innerHTML = '<div class="muted" style="font-size: 12px;">処理ルート情報が見つかりません</div>';
      }
    }
  }

  // 承認ステップ一覧の表示
  async function loadApprovalSteps(applicationId) {
    const steps = await window.aivicApi.list(tables.indexOf(approvalStepTable));
    const users = await window.aivicApi.list(tables.indexOf(userTable));

    if (steps && users) {
      const appSteps = steps.filter(s => s.申請書類ID === applicationId);

      if (appSteps.length > 0) {
        approvalStepsTbody.innerHTML = appSteps.map(step => {
          const approver = users.find(u => u.id === step.承認者ID);
          const approverName = approver ? approver.ユーザー名 : '不明';

          return `
            <tr>
              <td style="padding: 6px 10px; font-size: 12px;">${step.ステップ番号}</td>
              <td style="padding: 6px 10px; font-size: 12px;">${approverName}</td>
              <td style="padding: 6px 10px; font-size: 12px;">${step.承認状態}</td>
              <td style="padding: 6px 10px; font-size: 12px;">${step.期限日時 ? new Date(step.期限日時).toLocaleDateString() : '-'}</td>
            </tr>
          `;
        }).join('');
      } else {
        approvalStepsTbody.innerHTML = '<tr><td colspan="4" style="padding: 12px; text-align: center; color: var(--text-muted); font-size: 12px;">承認ステップが見つかりません</td></tr>';
      }
    }
  }

  // エラー表示
  function showError(message) {
    errorMessage.textContent = message;
    errorMessage.style.display = 'block';
    setTimeout(() => {
      errorMessage.style.display = 'none';
    }, 5000);
  }

  // バリデーション
  function validateForm() {
    if (!applicationSelect.value) {
      showError('申請書類を選択してください');
      return false;
    }

    if (!newRouteSelect.value) {
      showError('新しい処理ルートを選択してください');
      return false;
    }

    if (!changeReasonTextarea.value.trim()) {
      showError('変更理由を入力してください');
      return false;
    }

    // 同一処理ルート選択チェック
    if (currentRoute && currentRoute.承認フロー定義ID === newRouteSelect.value) {
      if (!confirm('現在と同じ処理ルートが選択されています。変更する必要がありますか？')) {
        return false;
      }
    }

    return true;
  }

  // 通知バリデーション
  function validateNotification() {
    const selectedTargets = container.querySelectorAll('input[name="notify-target"]:checked');
    if (selectedTargets.length === 0) {
      showError('通知対象者を選択してください');
      return false;
    }

    if (!notificationMessageTextarea.value.trim()) {
      showError('通知メッセージを入力してください');
      return false;
    }

    return true;
  }

  // イベントリスナー
  applicationSelect.addEventListener('change', (e) => {
    if (e.target.value) {
      displayCurrentRoute(e.target.value);
    } else {
      currentRouteDisplay.innerHTML = '<div class="muted" style="font-size: 12px;">申請書類を選択してください</div>';
      approvalStepsTbody.innerHTML = '<tr><td colspan="4" style="padding: 12px; text-align: center; color: var(--text-muted); font-size: 12px;">申請書類を選択してください</td></tr>';
    }
  });

  // 全選択・全解除
  container.querySelector('#select-all-btn').addEventListener('click', () => {
    container.querySelectorAll('input[name="notify-target"]').forEach(cb => cb.checked = true);
  });

  container.querySelector('#deselect-all-btn').addEventListener('click', () => {
    container.querySelectorAll('input[name="notify-target"]').forEach(cb => cb.checked = false);
  });

  // 承認者変更ボタン
  container.querySelector('#change-approver-btn').addEventListener('click', () => {
    if (!currentApplication) {
      showError('申請書類を選択してください');
      return;
    }
    alert('承認者変更機能は別画面で実装されます');
  });

  // 変更内容確認ボタン
  container.querySelector('#confirm-btn').addEventListener('click', () => {
    if (!validateForm()) return;

    const selectedRoute = newRouteSelect.options[newRouteSelect.selectedIndex].text;
    const reason = changeReasonTextarea.value;

    confirmationContent.innerHTML = `
      <div style="margin-bottom: 8px;"><strong>申請書類:</strong> ${applicationSelect.options[applicationSelect.selectedIndex].text}</div>
      <div style="margin-bottom: 8px;"><strong>新しい処理ルート:</strong> ${selectedRoute}</div>
      <div style="margin-bottom: 8px;"><strong>変更理由:</strong> ${reason}</div>
    `;

    confirmationModal.style.display = 'flex';
  });

  // 処理ルート変更実行ボタン
