    if (!validateForm()) return;

    try {
      // 処理ルートの更新
      const updated = await window.aivicApi.update(tables.indexOf(routeTable), currentRoute.id, {
        承認フロー定義ID: newRouteSelect.value,
        処理状況: '承認待ち',
