      const message = notificationMessageTextarea.value;

      // 各対象者に通知を送信
      for (const target of selectedTargets) {
        await window.aivicApi.save(tables.indexOf(notificationTable), {
          申請書類ID: applicationSelect.value,
          通知対象ユーザーID: target.value,
          通知種別: '処理ルート変更',
          通知タイトル: '処理ルート変更のお知らせ',
          通知内容: message,
          送信方法: 'システム内通知',
          送信状態: '送信完了',
          送信日時: new Date().toISOString(),
          既読フラグ: false,
          再送回数: 0,
          作成日時: new Date().toISOString(),
          作成者ID: 'current-user-id'
        });
      }

      alert('通知が正常に送信されました');
      // フォームリセット
      notificationMessageTextarea.value = '';
      messageCharCount.textContent = '0';
      container.querySelectorAll('input[name="notify-target"]').forEach(cb => cb.checked = false);
