  // キャンセルボタン
  container.querySelector('#cancel-btn').addEventListener('click', () => {
    if (confirm('入力内容がクリアされますが、よろしいですか？')) {
      // フォームリセット
      applicationSelect.value = '';
      newRouteSelect.value = '';
      changeReasonTextarea.value = '';
      notificationMessageTextarea.value = '';
      reasonCharCount.textContent = '0';
      messageCharCount.textContent = '0';
      currentRouteDisplay.innerHTML = '<div class="muted" style="font-size: 12px;">申請書類を選択してください</div>';
      approvalStepsTbody.innerHTML = '<tr><td colspan="4" style="padding: 12px; text-align: center; color: var(--text-muted); font-size: 12px;">申請書類を選択してください</td></tr>';
      container.querySelectorAll('input[name="notify-target"]').forEach(cb => cb.checked = false);
      currentApplication = null;
      currentRoute = null;
    }
  });

  // モーダルのイベントリスナー
  container.querySelector('#modal-cancel-btn').addEventListener('click', () => {
    confirmationModal.style.display = 'none';
  });

  container.querySelector('#modal-execute-btn').addEventListener('click', async () => {
    confirmationModal.style.display = 'none';

    try {
      // 処理ルートの更新
      const updated = await window.aivicApi.update(tables.indexOf(routeTable), currentRoute.id, {
        承認フロー定義ID: newRouteSelect.value,
        処理状況: '承認待ち',
        更新日時: new Date().toISOString(),
        更新者ID: 'current-user-id'
      });

      if (updated) {
        alert('処理ルートが正常に変更されました');
        displayCurrentRoute(applicationSelect.value);
      }
    } catch (error) {
      showError('処理ルートの変更に失敗しました');
    }
  });

  // 初期データ読み込み
  loadApplications();
  loadRoutes();
}

function(container, apiUrl, tables) {
  // 現在のユーザー情報を設定
  const currentUser = { name: "田中太郎", department: "総務部" };
  container.querySelector("#applicant").value = currentUser.name;

  // 今日の日付を設定
  const today = new Date().toISOString().split('T')[0];
  container.querySelector("#application-date").value = today;
  container.querySelector("#application-date").min = today;

  // 文字数カウンター
  function setupCharCounter(textareaId, counterId, maxLength) {
    const textarea = container.querySelector(`#${textareaId}`);
    const counter = container.querySelector(`#${counterId}`);

    textarea.addEventListener('input', () => {
      const length = textarea.value.length;
      counter.textContent = length;
      if (length > maxLength) {
        counter.style.color = '#dc2626';
      } else {
        counter.style.color = 'var(--text-muted)';
      }
    });
  }

  setupCharCounter('content-detail', 'content-counter', 2000);
  setupCharCounter('reason', 'reason-counter', 1000);

  // ファイルアップロード処理
  const fileInput = container.querySelector("#attachment");
  const fileList = container.querySelector("#file-list");

  fileInput.addEventListener('change', (e) => {
    const files = Array.from(e.target.files);
    const maxSize = 10 * 1024 * 1024; // 10MB
    const allowedTypes = ['.pdf', '.doc', '.docx', '.xls', '.xlsx', '.jpg', '.jpeg', '.png'];

    let validFiles = [];
    let errors = [];

    files.forEach(file => {
      const extension = '.' + file.name.split('.').pop().toLowerCase();

      if (!allowedTypes.includes(extension)) {
        errors.push(`${file.name}: サポートされていないファイル形式です`);
        return;
      }

      if (file.size > maxSize) {
        errors.push(`${file.name}: ファイルサイズが上限(10MB)を超えています`);
        return;
      }

      validFiles.push(file);
    });

    if (errors.length > 0) {
      showError(errors.join('\n'));
      fileInput.value = '';
      fileList.innerHTML = '';
    } else {
      fileList.innerHTML = validFiles.map(f => 
        `<div style="color: var(--text); font-size: 11px;">📎 ${f.name} (${Math.round(f.size/1024)}KB)</div>`
      ).join('');
    }
  });

  // エラー表示
  function showError(message) {
    const errorDiv = container.querySelector("#error-message");
    errorDiv.textContent = message;
    errorDiv.style.display = 'block';
    setTimeout(() => {
      errorDiv.style.display = 'none';
    }, 5000);
  }

  // バリデーション
  function validateForm() {
    const title = container.querySelector("#title").value.trim();
    const documentType = container.querySelector("#document-type").value;
    const applicationDate = container.querySelector("#application-date").value;
    const contentDetail = container.querySelector("#content-detail").value.trim();
    const reason = container.querySelector("#reason").value.trim();
    const amount = container.querySelector("#amount").value;
    const urgency = container.querySelector('input[name="urgency"]:checked');
    const approvalFlow = container.querySelector("#approval-flow").value;

    if (!title) {
      showError("申請書類タイトルを入力してください");
      return false;
    }

    if (title.length > 100) {
      showError("申請書類タイトルは100文字以内で入力してください");
      return false;
    }

    if (!documentType) {
      showError("文書種別を選択してください");
      return false;
    }

    if (!applicationDate) {
      showError("申請日付を選択してください");
      return false;
    }

    const selectedDate = new Date(applicationDate);
    const todayDate = new Date(today);
    if (selectedDate < todayDate) {
      showError("過去の日付は選択できません");
      return false;
    }

    if (!contentDetail) {
      showError("申請内容詳細を入力してください");
      return false;
    }

    if (contentDetail.length > 2000) {
      showError("申請内容詳細は2000文字以内で入力してください");
      return false;
    }

    if (!reason) {
      showError("申請理由を入力してください");
      return false;
    }

    if (reason.length > 1000) {
      showError("申請理由は1000文字以内で入力してください");
      return false;
    }

    if (amount && (isNaN(amount) || parseFloat(amount) < 0)) {
      showError("申請金額は正の数値を入力してください");
      return false;
    }

    if (amount && parseFloat(amount) > 9999999) {
      showError("申請金額は9,999,999円以下で入力してください");
      return false;
    }

    if (!urgency) {
      showError("緊急度を選択してください");
      return false;
    }

    if (!approvalFlow) {
      showError("承認フローを選択してください");
      return false;
    }

    return true;
  }

  // フォームデータ収集
  function collectFormData(status = '申請中') {
    const subsidies = Array.from(container.querySelectorAll('input[name="subsidy"]:checked')).map(cb => cb.value);
    const departments = Array.from(container.querySelectorAll('input[name="departments"]:checked')).map(cb => cb.value);
    const urgency = container.querySelector('input[name="urgency"]:checked')?.value;
    const files = container.querySelector("#attachment").files;

    return {
      申請種別: container.querySelector("#document-type").value,
      申請タイトル: container.querySelector("#title").value.trim(),
      申請内容: container.querySelector("#content-detail").value.trim(),
      申請金額: container.querySelector("#amount").value ? parseInt(container.querySelector("#amount").value) : null,
      申請開始日: container.querySelector("#application-date").value + 'T00:00:00Z',
      申請終了日: null,
      承認状態: status,
      現在承認者ID: null,
      承認段階: 1,
      最終承認者ID: null,
      最終承認日時: null,
      緊急フラグ: urgency === 'urgent' || urgency === 'high',
      添付ファイル有無: files && files.length > 0,
      備考: container.querySelector("#reason").value.trim(),
      作成者ID: 'current-user-id',
      更新者ID: 'current-user-id'
    };
  }

  // 下書き保存
  container.querySelector("#btn-draft").addEventListener("click", async () => {
    const title = container.querySelector("#title").value.trim();
    if (!title) {
      showError("申請書類タイトルを入力してください");
      return;
    }

    const formData = collectFormData('下書き');
    const saved = await window.aivicApi.save(1, formData); // 申請書類テーブル

    if (saved) {
      alert("下書きを保存しました");
      // フォームをクリア
      container.querySelector("#application-form").reset();
      container.querySelector("#applicant").value = currentUser.name;
      container.querySelector("#application-date").value = today;
      container.querySelector('input[name="urgency"][value="normal"]').checked = true;
      container.querySelector("#file-list").innerHTML = '';
    }
  });

  // 申請書類作成
  container.querySelector("#btn-submit").addEventListener("click", async () => {
    if (!validateForm()) return;

    const formData = collectFormData('申請中');
    const saved = await window.aivicApi.save(1, formData); // 申請書類テーブル

    if (saved) {
      alert("申請書類を作成しました");
      // フォームをクリア
      container.querySelector("#application-form").reset();
      container.querySelector("#applicant").value = currentUser.name;
      container.querySelector("#application-date").value = today;
      container.querySelector('input[name="urgency"][value="normal"]').checked = true;
      container.querySelector("#file-list").innerHTML = '';
    }
  });

  // キャンセル
  container.querySelector("#btn-cancel").addEventListener("click", () => {
    if (confirm("入力内容が失われますが、よろしいですか？")) {
      container.querySelector("#application-form").reset();
      container.querySelector("#applicant").value = currentUser.name;
      container.querySelector("#application-date").value = today;
      container.querySelector('input[name="urgency"][value="normal"]').checked = true;
      container.querySelector("#file-list").innerHTML = '';
    }
  });

  // 書類アップロードボタン
  container.querySelector("#btn-upload").addEventListener("click", () => {
    window.showScreen("scr-1779422207222");
  });

  // フォーカス時のスタイル適用
  const inputs = container.querySelectorAll('input, select, textarea');
  inputs.forEach(input => {
    input.addEventListener('focus', () => {
      input.style.outline = 'none';
      input.style.borderColor = 'var(--primary)';
      input.style.boxShadow = '0 0 0 2px rgba(255,255,255,0.08)';
    });

    input.addEventListener('blur', () => {
      input.style.borderColor = 'rgba(255,255,255,0.18)';
      input.style.boxShadow = 'none';
    });
  });
}

function(container, apiUrl, tables) {
  let currentFile = null;
  let currentAnalysisResult = null;

  // 処理ログ再描画関数
  function renderProcessLogs(logs) {
    const tbody = container.querySelector("#process-log-tbody");
    if (!logs || logs.length === 0) {
      tbody.innerHTML = '<tr><td colspan="7" style="text-align: center; color: var(--text-muted); padding: 20px;">処理ログがありません</td></tr>';
      return;
    }

    tbody.innerHTML = logs.map(log => `
      <tr data-id="${log.id || ''}">
        <td>${log.実行日時 || new Date().toLocaleString()}</td>
        <td>${log.処理内容 || '文書種別判別'}</td>
        <td>${log.ファイル名 || '-'}</td>
        <td>${log.判別結果 || '-'}</td>
        <td>${log.精度スコア || '-'}</td>
        <td>${log.処理時間 || '-'}</td>
        <td><span style="padding: 2px 6px; border-radius: 4px; font-size: 11px; background: ${log.ステータス === '成功' ? 'rgba(34, 197, 94, 0.2)' : log.ステータス === '失敗' ? 'rgba(220, 38, 38, 0.2)' : 'rgba(156, 163, 175, 0.2)'}; color: ${log.ステータス === '成功' ? '#86efac' : log.ステータス === '失敗' ? '#fca5a5' : '#d1d5db'}">${log.ステータス || '処理中'}</span></td>
      </tr>
    `).join("");
  }

  // 初期データ表示
  if (tables && tables[0] && tables[0].records) {
    renderProcessLogs(tables[0].records);
  }

  // メッセージ表示関数
  function showMessage(message, isError = false) {
    const errorEl = container.querySelector("#error-message");
    const successEl = container.querySelector("#success-message");

    if (isError) {
      errorEl.textContent = message;
      errorEl.style.display = "block";
      successEl.style.display = "none";
    } else {
      successEl.textContent = message;
      successEl.style.display = "block";
      errorEl.style.display = "none";
    }

    setTimeout(() => {
      errorEl.style.display = "none";
      successEl.style.display = "none";
    }, 5000);
  }

  // ファイル選択処理
  const fileInput = container.querySelector("#file-input");
  const selectFileBtn = container.querySelector("#select-file-btn");
  const uploadArea = container.querySelector("#upload-area");
  const fileInfo = container.querySelector("#file-info");
  const uploadBtn = container.querySelector("#upload-btn");

  selectFileBtn.addEventListener("click", () => {
    fileInput.click();
  });

  uploadArea.addEventListener("click", () => {
    fileInput.click();
  });

  uploadArea.addEventListener("dragover", (e) => {
    e.preventDefault();
    uploadArea.style.borderColor = "var(--primary)";
    uploadArea.style.background = "rgba(0,0,0,0.25)";
  });

  uploadArea.addEventListener("dragleave", (e) => {
    e.preventDefault();
    uploadArea.style.borderColor = "rgba(255,255,255,0.18)";
    uploadArea.style.background = "rgba(0,0,0,0.15)";
  });

  uploadArea.addEventListener("drop", (e) => {
    e.preventDefault();
    uploadArea.style.borderColor = "rgba(255,255,255,0.18)";
    uploadArea.style.background = "rgba(0,0,0,0.15)";

    const files = e.dataTransfer.files;
    if (files.length > 0) {
      handleFileSelection(files[0]);
    }
  });

  fileInput.addEventListener("change", (e) => {
    if (e.target.files.length > 0) {
      handleFileSelection(e.target.files[0]);
    }
  });

  function handleFileSelection(file) {
    // ファイル形式チェック
    const allowedTypes = ['.pdf', '.doc', '.docx', '.xls', '.xlsx'];
    const fileExt = '.' + file.name.split('.').pop().toLowerCase();

    if (!allowedTypes.includes(fileExt)) {
      showMessage("対応していないファイル形式です。PDF、Word、Excelファイルを選択してください。", true);
      return;
    }

    // ファイルサイズチェック（50MB制限）
    const maxSize = 50 * 1024 * 1024;
    if (file.size > maxSize) {
      showMessage("ファイルサイズが制限を超えています。50MB以下のファイルを選択してください。", true);
      return;
    }

    currentFile = file;

    // ファイル情報表示
    fileInfo.innerHTML = `
      <div><strong>ファイル名:</strong> ${file.name}</div>
      <div><strong>サイズ:</strong> ${(file.size / 1024 / 1024).toFixed(2)} MB</div>
      <div><strong>種別:</strong> ${file.type || 'unknown'}</div>
    `;
    fileInfo.style.display = "block";

    uploadBtn.disabled = false;

    // プレビュー表示
    const preview = container.querySelector("#document-preview");
    if (file.type.includes('image')) {
      const reader = new FileReader();
      reader.onload = (e) => {
        preview.innerHTML = `<img src="${e.target.result}" style="max-width: 100%; max-height: 100%; object-fit: contain;">`;
      };
      reader.readAsDataURL(file);
    } else {
      preview.innerHTML = `<div style="text-align: center; color: var(--text-muted);">
        <div style="font-size: 48px; margin-bottom: 8px;">📄</div>
        <div>${file.name}</div>
        <div style="font-size: 11px; margin-top: 4px;">${(file.size / 1024 / 1024).toFixed(2)} MB</div>
      </div>`;
    }
  }

  // アップロード・解析処理
  uploadBtn.addEventListener("click", async () => {
    if (!currentFile) {
      showMessage("ファイルを選択してください。", true);
      return;
    }

    uploadBtn.disabled = true;
    uploadBtn.textContent = "解析中...";

    try {
      // 文書種別判別シミュレーション
      await new Promise(resolve => setTimeout(resolve, 2000));

      // ランダムな判別結果生成
      const docTypes = ["申請書", "報告書", "契約書", "稟議書", "請求書", "見積書"];
      const randomType = docTypes[Math.floor(Math.random() * docTypes.length)];
      const accuracy = (Math.random() * 0.4 + 0.6).toFixed(2); // 0.6-1.0の範囲

      // 結果表示
      container.querySelector("#auto-detection-result").textContent = randomType;
      container.querySelector("#accuracy-score").textContent = `${(accuracy * 100).toFixed(1)}%`;

      // 補助金関連度判定
      const relevanceLevel = Math.random() > 0.5 ? "高" : Math.random() > 0.3 ? "中" : "低";
      container.querySelector("#subsidy-relevance").textContent = relevanceLevel;

      // OCR結果シミュレーション
      const ocrResults = container.querySelector("#ocr-results");
      ocrResults.innerHTML = `
        <div style="margin-bottom: 8px; font-weight: 600;">抽出テキスト:</div>
        <div style="background: rgba(0,0,0,0.2); padding: 8px; border-radius: 4px; margin-bottom: 8px;">
          ${randomType}書<br>
          申請者: 田中太郎<br>
          申請日: ${new Date().toLocaleDateString()}<br>
          件名: システム導入に関する申請<br>
          金額: 1,000,000円
        </div>
        <div style="font-size: 11px; color: var(--text-muted);">
          文字認識率: ${(accuracy * 100).toFixed(1)}% | 処理時間: 1.8秒
        </div>
      `;

      // キーワード抽出結果
      const keywords = ["申請", "承認", "システム", "導入", "予算", "効果"];
      const keywordResults = container.querySelector("#keyword-results");
      keywordResults.innerHTML = keywords.map(keyword => 
        `<span style="display: inline-block; background: rgba(59, 130, 246, 0.2); color: #93c5fd; padding: 2px 6px; border-radius: 4px; font-size: 11px; margin: 2px;">${keyword}</span>`
      ).join("");

      // 承認フロー自動設定
      const approvalFlow = container.querySelector("#approval-flow");
      approvalFlow.innerHTML = `
        <div style="font-size: 12px; margin-bottom: 8px;">
          <div style="margin-bottom: 4px;"><strong>承認段数:</strong> 3段階</div>
          <div style="margin-bottom: 4px;"><strong>承認者:</strong></div>
          <div style="margin-left: 12px; font-size: 11px; color: var(--text-muted);">
            1. 直属上司 (田中部長)<br>
            2. 部門責任者 (佐藤取締役)<br>
            3. 最終承認者 (山田社長)
          </div>
        </div>
      `;

      currentAnalysisResult = {
        fileName: currentFile.name,
        docType: randomType,
        accuracy: accuracy,
        relevance: relevanceLevel
      };

      // ボタン状態更新
      container.querySelector("#confirm-result-btn").disabled = false;
      container.querySelector("#re-analyze-btn").disabled = false;

      // 処理ログに追加
      const logEntry = {
        id: Date.now().toString(),
        実行日時: new Date().toLocaleString(),
        処理内容: "文書種別判別",
        ファイル名: currentFile.name,
        判別結果: randomType,
        精度スコア: `${(accuracy * 100).toFixed(1)}%`,
        処理時間: "1.8秒",
        ステータス: "成功"
      };

      if (window.aivicApi) {
        await window.aivicApi.save(0, logEntry);
        const logs = await window.aivicApi.list(0);
        renderProcessLogs(logs);
      }

      showMessage("文書種別判別が完了しました。");

    } catch (error) {
      showMessage("文書種別判別に失敗しました: " + error.message, true);

      // エラーログ追加
      const errorLog = {
        id: Date.now().toString(),
        実行日時: new Date().toLocaleString(),
        処理内容: "文書種別判別",
        ファイル名: currentFile ? currentFile.name : "-",
        判別結果: "エラー",
        精度スコア: "0%",
        処理時間: "-",
        ステータス: "失敗"
      };

      if (window.aivicApi) {
        await window.aivicApi.save(0, errorLog);
        const logs = await window.aivicApi.list(0);
        renderProcessLogs(logs);
      }
    } finally {
      uploadBtn.disabled = false;
      uploadBtn.textContent = "アップロード";
    }
  });

  // 再判別実行
  container.querySelector("#re-analyze-btn").addEventListener("click", async () => {
    if (!currentFile) {
      showMessage("ファイルを選択してください。", true);
      return;
    }

    if (!confirm("再判別を実行しますか？")) {
      return;
    }

    // アップロードボタンのクリックをトリガー
    uploadBtn.click();
  });

  // 手動選択での上書き
  container.querySelector("#manual-doc-type").addEventListener("change", (e) => {
    if (e.target.value && currentAnalysisResult) {
      currentAnalysisResult.docType = e.target.value;
      container.querySelector("#auto-detection-result").textContent = e.target.value + " (手動選択)";
      showMessage("文書種別を手動で変更しました。");
    }
  });

  // 判別結果確定
  container.querySelector("#confirm-result-btn").addEventListener("click", () => {
    if (!currentAnalysisResult) {
      showMessage("判別結果がありません。", true);
      return;
    }

    showMessage("判別結果を確定しました。申請内容入力画面に遷移します。");

    setTimeout(() => {
      window.showScreen("scr-1779422326698"); // 申請書類作成画面
    }, 1500);
  });

  // 初期ログデータ読み込み
  if (window.aivicApi) {
    window.aivicApi.list(0).then(logs => {
      renderProcessLogs(logs);
    }).catch(error => {
      console.error("ログデータの読み込みに失敗:", error);
    });
  }
}

function(container, apiUrl, tables) {
  const tbody = container.querySelector("#results-tbody");
  const resultCount = container.querySelector("#result-count");
  const errorMessage = container.querySelector("#error-message");
  const thresholdSlider = container.querySelector("#days-threshold");
  const thresholdDisplay = container.querySelector("#threshold-display");

  // 滞留日数計算
  function calculateDelayDays(createdDate) {
    const created = new Date(createdDate);
    const now = new Date();
    const diffTime = Math.abs(now - created);
    return Math.ceil(diffTime / (1000 * 60 * 60 * 24));
  }

  // 緊急度表示
  function getPriorityBadge(priority) {
    const colors = {
      '高': 'background: rgba(255,0,0,0.2); color: #ff6666; border: 1px solid rgba(255,0,0,0.3);',
      '中': 'background: rgba(255,165,0,0.2); color: #ffaa00; border: 1px solid rgba(255,165,0,0.3);',
      '低': 'background: rgba(0,128,0,0.2); color: #66cc66; border: 1px solid rgba(0,128,0,0.3);'
    };
    const style = colors[priority] || colors['低'];
    return `<span style="padding: 2px 6px; border-radius: 4px; font-size: 11px; ${style}">${priority}</span>`;
  }

  // テーブル再描画関数
  function renderRows(rows) {
    if (!rows || rows.length === 0) {
      tbody.innerHTML = '<tr><td colspan="8" style="padding: 20px; text-align: center; color: var(--text-muted);">該当する滞留案件はありません</td></tr>';
      resultCount.textContent = '0件';
      return;
    }

    tbody.innerHTML = rows.map(r => {
      const delayDays = calculateDelayDays(r.作成日時 || new Date());
      const priority = r.優先度 === 4 ? '高' : r.優先度 === 3 ? '中' : '低';

      return `
        <tr data-id="${r.申請書類ID || r.id}" style="border-bottom: 1px solid rgba(255,255,255,0.05);">
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${r.申請書類ID || 'APP-' + Math.random().toString(36).substr(2, 8).toUpperCase()}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${r.申請種別 || '休暇申請'}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${r.申請者名 || 'テスト太郎'}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${r.現在承認者名 || '田中部長'}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${r.承認段階 || 1}段階目</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text); font-weight: 600;">${delayDays}日</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${getPriorityBadge(priority)}</td>
          <td style="padding: 6px 10px; font-size: 13px;">
            <button class="action-btn secondary detail-btn" data-id="${r.申請書類ID || r.id}" style="margin-right: 4px;">詳細</button>
            <button class="action-btn secondary notify-btn" data-id="${r.申請書類ID || r.id}">催促</button>
          </td>
        </tr>
      `;
    }).join('');

    resultCount.textContent = `${rows.length}件`;
  }

  // エラー表示
  function showError(message) {
    errorMessage.textContent = message;
    errorMessage.style.display = 'block';
    setTimeout(() => {
      errorMessage.style.display = 'none';
    }, 5000);
  }

  // 検索条件バリデーション
  function validateSearchConditions() {
    const startDate = container.querySelector("#start-date").value;
    const endDate = container.querySelector("#end-date").value;
    const applicantName = container.querySelector("#applicant-name").value;
    const documentNumber = container.querySelector("#document-number").value;

    // 日付範囲チェック
    if (startDate && endDate && new Date(startDate) > new Date(endDate)) {
      showError('終了日は開始日以降の日付を入力してください');
      return false;
    }

    // 不正文字列チェック
    const dangerousPatterns = [
      /<script/i,
      /javascript:/i,
      /';.*drop.*table/i,
      /union.*select/i
    ];

    const inputs = [applicantName, documentNumber];
    for (const input of inputs) {
      if (input && dangerousPatterns.some(pattern => pattern.test(input))) {
        showError('不正な文字列が含まれています');
        return false;
      }
      if (input && input.length > 1000) {
        showError('入力文字数が上限を超えています');
        return false;
      }
    }

    return true;
  }

  // 検索フィルタ
  function filterRows(rows) {
    const startDate = container.querySelector("#start-date").value;
    const endDate = container.querySelector("#end-date").value;
    const documentType = container.querySelector("#document-type").value;
    const applicantName = container.querySelector("#applicant-name").value.toLowerCase();
    const assignee = container.querySelector("#assignee").value;
    const documentNumber = container.querySelector("#document-number").value;
    const thresholdDays = parseInt(thresholdSlider.value);
    const selectedPriority = container.querySelector('input[name="priority"]:checked')?.value;

    const selectedSteps = Array.from(container.querySelectorAll('input[type="checkbox"]:checked'))
      .map(cb => cb.value);

    return rows.filter(row => {
      // 日付範囲フィルタ
      if (startDate) {
        const rowDate = new Date(row.作成日時 || new Date());
        if (rowDate < new Date(startDate)) return false;
      }
      if (endDate) {
        const rowDate = new Date(row.作成日時 || new Date());
        if (rowDate > new Date(endDate)) return false;
      }

      // 文書種別フィルタ
      if (documentType && (row.申請種別 || '休暇申請') !== documentType) return false;

      // 申請者名フィルタ（部分一致）
      if (applicantName && !(row.申請者名 || 'テスト太郎').toLowerCase().includes(applicantName)) return false;

      // 担当者フィルタ
      if (assignee && (row.現在承認者名 || '田中部長') !== assignee) return false;

      // 申請書類番号フィルタ（完全一致）
      if (documentNumber) {
        const rowDocNumber = row.申請書類ID || 'APP-' + Math.random().toString(36).substr(2, 8).toUpperCase();
        if (rowDocNumber !== documentNumber) return false;
      }

      // 滞留日数フィルタ
      const delayDays = calculateDelayDays(row.作成日時 || new Date());
      if (delayDays < thresholdDays) return false;

      // 緊急度フィルタ
      if (selectedPriority) {
        const rowPriority = row.優先度 === 4 ? '高' : row.優先度 === 3 ? '中' : '低';
        if (rowPriority !== selectedPriority) return false;
      }

      // 承認ステップフィルタ
      if (selectedSteps.length > 0) {
        const currentStep = row.現在ステップ || '部長承認';
        if (!selectedSteps.includes(currentStep)) return false;
      }

      return true;
    });
  }

  // CSVエクスポート
  function exportCSV(rows) {
    const headers = ['申請書類番号', '文書種別', '申請者', '現在承認者', '承認段階', '滞留日数', '緊急度', '作成日時'];
    const csvData = [headers];

    rows.forEach(row => {
      const delayDays = calculateDelayDays(row.作成日時 || new Date());
      const priority = row.優先度 === 4 ? '高' : row.優先度 === 3 ? '中' : '低';

      csvData.push([
        row.申請書類ID || 'APP-' + Math.random().toString(36).substr(2, 8).toUpperCase(),
        row.申請種別 || '休暇申請',
        row.申請者名 || 'テスト太郎',
        row.現在承認者名 || '田中部長',
        (row.承認段階 || 1) + '段階目',
        delayDays + '日',
        priority,
        row.作成日時 || new Date().toISOString()
      ]);
    });

    const csvContent = '\uFEFF' + csvData.map(row => 
      row.map(field => `"${String(field).replace(/"/g, '""')}"`).join(',')
    ).join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `滞留案件一覧_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  }

  // 初期データ読み込み
  window.aivicApi.list(1).then(rows => {
    if (rows) {
      renderRows(rows);
    } else {
      renderRows(tables[1]?.records || []);
    }
  });

  // スライダー値表示更新
  thresholdSlider.addEventListener('input', () => {
    thresholdDisplay.textContent = thresholdSlider.value;
  });

  // 検索ボタン
  container.querySelector("#btn-search").addEventListener("click", async () => {
    if (!validateSearchConditions()) return;

    try {
      const allRows = await window.aivicApi.list(1);
      if (allRows) {
        const filteredRows = filterRows(allRows);
        renderRows(filteredRows);
      } else {
        showError('データの取得に失敗しました');
      }
    } catch (error) {
      showError('検索処理でエラーが発生しました');
    }
  });

  // クリアボタン
  container.querySelector("#btn-clear").addEventListener("click", () => {
    container.querySelector("#start-date").value = '';
    container.querySelector("#end-date").value = '';
    container.querySelector("#document-type").value = '';
    container.querySelector("#applicant-name").value = '';
    container.querySelector("#assignee").value = '';
    container.querySelector("#document-number").value = '';
    thresholdSlider.value = '7';
    thresholdDisplay.textContent = '7';

    container.querySelectorAll('input[type="checkbox"]').forEach(cb => cb.checked = false);
    container.querySelectorAll('input[type="radio"]').forEach(rb => rb.checked = false);

    errorMessage.style.display = 'none';

    // 全件再表示
    window.aivicApi.list(1).then(rows => {
      if (rows) {
        renderRows(rows);
      } else {
        renderRows(tables[1]?.records || []);
      }
    });
  });

  // CSVエクスポートボタン
  container.querySelector("#btn-export").addEventListener("click", async () => {
    try {
      const allRows = await window.aivicApi.list(1);
      if (allRows) {
        const filteredRows = filterRows(allRows);
        exportCSV(filteredRows);
      } else {
        showError('エクスポートするデータがありません');
      }
    } catch (error) {
      showError('CSVエクスポートでエラーが発生しました');
    }
  });

  // 行レベル操作（詳細・催促）
  container.addEventListener("click", async (e) => {
    const detailBtn = e.target.closest(".detail-btn");
    const notifyBtn = e.target.closest(".notify-btn");

    if (detailBtn) {
      const id = detailBtn.dataset.id;
      window.showScreen("scr-1779422434952"); // 申請書類確認画面
    }

    if (notifyBtn) {
      const id = notifyBtn.dataset.id;
      if (confirm('催促通知を送信しますか？')) {
        window.showScreen("scr-1779422392638"); // 催促通知送信処理
      }
    }
  });
}

function(container, apiUrl, tables) {
  let currentData = [];
  let sortDirection = 'asc';
  let selectedItems = new Set();

  // 緊急度レベルの表示変換
  function getUrgencyLabel(level) {
    const labels = { 1: '低', 2: '中', 3: '高', 4: '緊急' };
    return labels[level] || '不明';
  }

  // 緊急度レベルの色分け
  function getUrgencyColor(level) {
    const colors = {
      1: '#6b7280', // 低: グレー
      2: '#3b82f6', // 中: ブルー
      3: '#f59e0b', // 高: オレンジ
      4: '#dc2626'  // 緊急: レッド
    };
    return colors[level] || '#6b7280';
  }

  // 遅延日数計算
  function calculateDelayDays(createdDate, currentDate = new Date()) {
    const created = new Date(createdDate);
    const diffTime = currentDate - created;
    return Math.floor(diffTime / (1000 * 60 * 60 * 24));
  }

  // テーブル再描画関数
  function renderRows(rows) {
    const tbody = container.querySelector('#delayed-applications-tbody');
    const noDataMessage = container.querySelector('#no-data-message');

    if (!rows || rows.length === 0) {
      tbody.innerHTML = '';
      noDataMessage.style.display = 'block';
      return;
    }

    noDataMessage.style.display = 'none';

    tbody.innerHTML = rows.map(row => {
      const delayDays = calculateDelayDays(row.作成日時);
      const urgencyColor = getUrgencyColor(row.優先度 || 2);
      const isSelected = selectedItems.has(row.申請書類ID);

      return `
        <tr data-id="${row.申請書類ID}" style="height: 36px; border-bottom: 1px solid rgba(255,255,255,0.02);">
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">
            <input type="checkbox" class="row-checkbox" data-id="${row.申請書類ID}" ${isSelected ? 'checked' : ''} style="accent-color: var(--primary);">
          </td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${row.申請書類ID?.substring(0, 8) || 'N/A'}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${row.申請者名 || 'N/A'}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${row.申請種別 || 'N/A'}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${new Date(row.作成日時).toLocaleDateString('ja-JP') || 'N/A'}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${row.承認段階 || 1}段階目</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${row.承認者名 || 'N/A'}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: ${delayDays > 7 ? '#dc2626' : delayDays > 3 ? '#f59e0b' : 'var(--text)'};">
            ${delayDays > 30 ? '30日以上' : delayDays + '日'}
          </td>
          <td style="padding: 6px 10px; font-size: 13px;">
            <span style="background: ${urgencyColor}; color: #fff; padding: 2px 6px; border-radius: 4px; font-size: 11px;">
              ${getUrgencyLabel(row.優先度 || 2)}
            </span>
          </td>
          <td style="padding: 6px 10px; text-align: center;">
            <button class="action-btn secondary remind-btn" data-id="${row.申請書類ID}" data-testid="individual-remind-button" style="background: transparent; color: var(--text); border: 1px solid rgba(255,255,255,0.18); padding: 4px 8px; border-radius: 4px; font-size: 11px; cursor: pointer;">催促</button>
          </td>
        </tr>
      `;
    }).join('');
  }

  // フィルタリング関数
  function filterData() {
    const keyword = container.querySelector('#search-keyword').value.toLowerCase();
    const urgencyFilter = container.querySelector('#urgency-filter').value;
    const delayFilter = container.querySelector('#delay-filter').value;

    let filtered = currentData.filter(row => {
      // キーワード検索
      if (keyword) {
        const searchText = `${row.申請者名 || ''} ${row.申請書類ID || ''} ${row.申請種別 || ''}`.toLowerCase();
        if (!searchText.includes(keyword)) return false;
      }

      // 緊急度フィルター
      if (urgencyFilter && (row.優先度 || 2).toString() !== urgencyFilter) {
        return false;
      }

      // 遅延日数フィルター
      if (delayFilter) {
        const delayDays = calculateDelayDays(row.作成日時);
        switch (delayFilter) {
          case '1-3': if (delayDays < 1 || delayDays > 3) return false; break;
          case '4-7': if (delayDays < 4 || delayDays > 7) return false; break;
          case '8-14': if (delayDays < 8 || delayDays > 14) return false; break;
          case '15+': if (delayDays < 15) return false; break;
        }
      }

      return true;
    });

    renderRows(filtered);
  }

  // ソート機能
  function sortByDelayDays() {
    const sortIcon = container.querySelector('#sort-icon');
    sortDirection = sortDirection === 'asc' ? 'desc' : 'asc';

    currentData.sort((a, b) => {
      const delayA = calculateDelayDays(a.作成日時);
      const delayB = calculateDelayDays(b.作成日時);
      return sortDirection === 'asc' ? delayA - delayB : delayB - delayA;
    });

    sortIcon.textContent = sortDirection === 'asc' ? '↑' : '↓';
    filterData();
  }

  // メッセージ表示
  function showMessage(message, isError = false) {
    const errorEl = container.querySelector('#error-message');
    const successEl = container.querySelector('#success-message');

    if (isError) {
      errorEl.textContent = message;
      errorEl.style.display = 'block';
      successEl.style.display = 'none';
      setTimeout(() => errorEl.style.display = 'none', 5000);
    } else {
      successEl.textContent = message;
      successEl.style.display = 'block';
      errorEl.style.display = 'none';
      setTimeout(() => successEl.style.display = 'none', 5000);
    }
  }

  // 催促通知送信
  async function sendReminder(applicationIds, isBulk = false) {
    try {
      // 通知履歴テーブルのインデックスを取得
      const notificationHistoryIndex = tables.findIndex(t => t.tableName === '通知履歴');

      if (notificationHistoryIndex === -1) {
        throw new Error('通知履歴テーブルが見つかりません');
      }

      const notifications = [];
      const currentTime = new Date().toISOString();

      for (const appId of applicationIds) {
        const application = currentData.find(app => app.申請書類ID === appId);
        if (!application) continue;

        // 承認者のメールアドレスチェック（簡易実装）
        if (!application.承認者メール && Math.random() < 0.1) { // 10%の確率でメールアドレス未設定エラー
          throw new Error('承認者のメールアドレスが設定されていないため、催促通知を送信できません');
        }

        const notification = {
          通知履歴ID: crypto.randomUUID(),
          申請書類ID: appId,
          通知対象ユーザーID: application.現在承認者ID || crypto.randomUUID(),
          通知種別: '催促通知',
          通知タイトル: `【催促】申請書類の承認をお願いします（${application.申請種別}）`,
          通知内容: `申請者: ${application.申請者名}\n申請種別: ${application.申請種別}\n申請日: ${new Date(application.作成日時).toLocaleDateString('ja-JP')}\n\n承認をお待ちしております。`,
          送信方法: 'メール',
          送信先アドレス: application.承認者メール || 'approver@example.com',
          送信状態: '送信完了',
          送信日時: currentTime,
          既読フラグ: false,
          エラーメッセージ: null,
          再送回数: 0,
          作成日時: currentTime,
          更新日時: currentTime,
          作成者ID: crypto.randomUUID()
        };

        notifications.push(notification);
      }

      // 通知履歴に保存
      for (const notification of notifications) {
        await window.aivicApi.save(notificationHistoryIndex, notification);
      }

      const message = isBulk 
        ? `${notifications.length}件の催促通知を送信しました`
        : '催促通知を送信しました';

      showMessage(message);

      // 選択をクリア
      selectedItems.clear();
      container.querySelector('#select-all').checked = false;
      filterData();

    } catch (error) {
      console.error('催促通知送信エラー:', error);
      showMessage(error.message, true);
    }
  }

  // CSVエクスポート
  function exportCSV() {
    const headers = ['申請書類番号', '申請者名', '文書種別', '申請日', '現在承認ステップ', '承認者名', '遅延日数', '緊急度'];
    const csvData = currentData.map(row => [
      row.申請書類ID?.substring(0, 8) || '',
      row.申請者名 || '',
      row.申請種別 || '',
      new Date(row.作成日時).toLocaleDateString('ja-JP'),
      (row.承認段階 || 1) + '段階目',
      row.承認者名 || '',
      calculateDelayDays(row.作成日時) + '日',
      getUrgencyLabel(row.優先度 || 2)
    ]);

    const csvContent = '\uFEFF' + [headers, ...csvData]
      .map(row => row.map(field => `"${field}"`).join(','))
      .join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `遅延申請一覧_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  }

  // 初期データ読み込み
  async function loadData() {
    try {
      const applications = await window.aivicApi.list(1); // 申請書類テーブル
      const users = await window.aivicApi.list(0); // ユーザーテーブル

      if (!applications) {
        currentData = tables[1]?.records || [];
      } else {
        // 承認待ちで遅延している申請のみフィルタ
        currentData = applications.filter(app => {
          const delayDays = calculateDelayDays(app.作成日時);
          return app.承認状態 === '申請中' && delayDays > 0;
        }).map(app => {
          // 承認者名を取得
          const approver = users?.find(u => u.ユーザーID === app.現在承認者ID);
          return {
            ...app,
            申請者名: users?.find(u => u.ユーザーID === app.申請者ID)?.ユーザー名 || 'N/A',
            承認者名: approver?.ユーザー名 || 'N/A',
            承認者メール: approver?.メールアドレス
          };
        });
      }

      renderRows(currentData);
    } catch (error) {
      console.error('データ読み込みエラー:', error);
      currentData = tables[1]?.records || [];
      renderRows(currentData);
    }
  }

  // イベントリスナー設定
  container.querySelector('#btn-search').addEventListener('click', filterData);

  container.querySelector('#sort-delay-days').addEventListener('click', sortByDelayDays);

  // 全選択チェックボックス
  container.querySelector('#select-all').addEventListener('change', (e) => {
    const checkboxes = container.querySelectorAll('.row-checkbox');
    checkboxes.forEach(cb => {
      cb.checked = e.target.checked;
      if (e.target.checked) {
        selectedItems.add(cb.dataset.id);
      } else {
        selectedItems.delete(cb.dataset.id);
      }
    });
  });

  // 一括催促ボタン
  container.querySelector('#btn-bulk-remind').addEventListener('click', () => {
    if (selectedItems.size === 0) {
      showMessage('催促対象の申請を選択してください', true);
      return;
    }

    const modal = container.querySelector('#remind-modal');
    const content = container.querySelector('#remind-content');
    content.innerHTML = `選択した${selectedItems.size}件の申請に対して催促通知を送信しますか？`;
    modal.style.display = 'flex';
  });

  // CSVエクスポート
  container.querySelector('#btn-export-csv').addEventListener('click', exportCSV);

  // モーダル制御
  container.querySelector('#btn-cancel-remind').addEventListener('click', () => {
    container.querySelector('#remind-modal').style.display = 'none';
  });

  container.querySelector('#btn-confirm-remind').addEventListener('click', async () => {
    container.querySelector('#remind-modal').style.display = 'none';
    await sendReminder(Array.from(selectedItems), true);
  });

  // イベントデリゲーション
  container.addEventListener('click', async (e) => {
    // 行選択チェックボックス
    const checkbox = e.target.closest('.row-checkbox');
    if (checkbox) {
      const id = checkbox.dataset.id;
      if (checkbox.checked) {
        selectedItems.add(id);
      } else {
        selectedItems.delete(id);
      }

      // 全選択チェックボックスの状態更新
      const allCheckboxes = container.querySelectorAll('.row-checkbox');
      const checkedCount = container.querySelectorAll('.row-checkbox:checked').length;
      const selectAllCheckbox = container.querySelector('#select-all');
      selectAllCheckbox.checked = checkedCount === allCheckboxes.length;
      selectAllCheckbox.indeterminate = checkedCount > 0 && checkedCount < allCheckboxes.length;
    }

    // 個別催促ボタン
    const remindBtn = e.target.closest('.remind-btn');
    if (remindBtn) {
      const appId = remindBtn.dataset.id;
      const application = currentData.find(app => app.申請書類ID === appId);

      const modal = container.querySelector('#remind-modal');
      const content = container.querySelector('#remind-content');
      content.innerHTML = `
        <strong>申請書類:</strong> ${application?.申請種別 || 'N/A'}<br>
        <strong>申請者:</strong> ${application?.申請者名 || 'N/A'}<br>
        <strong>承認者:</strong> ${application?.承認者名 || 'N/A'}<br><br>
        この申請に対して催促通知を送信しますか？
      `;
      modal.style.display = 'flex';

      // 確認ボタンのイベントを一時的に変更
      const confirmBtn = container.querySelector('#btn-confirm-remind');
      const newConfirmBtn = confirmBtn.cloneNode(true);
      confirmBtn.parentNode.replaceChild(newConfirmBtn, confirmBtn);

      newConfirmBtn.addEventListener('click', async () => {
        modal.style.display = 'none';
        await sendReminder([appId], false);
      });
    }
  });

  // 初期データ読み込み
  loadData();
}

function(container, apiUrl, tables) {
  const tbody = container.querySelector('#notification-tbody');
  const unreadBadge = container.querySelector('#unread-badge');
  const delayAlert = container.querySelector('#delay-alert');
  const delayDetails = container.querySelector('#delay-details');
  const emptyMessage = container.querySelector('#empty-message');
  const applicantFilter = container.querySelector('#applicant-filter');

  let allNotifications = [];
  let currentFilters = {
    priority: '',
    documentType: '',
    applicant: '',
    deadline: ''
  };

  function getPriorityIcon(priority) {
    switch(priority) {
      case 4: return '<span style="color: #ff4757; font-weight: bold;">🔴 緊急</span>';
      case 3: return '<span style="color: #ff6348; font-weight: bold;">🟠 高</span>';
      case 2: return '<span style="color: #ffa502;">🟡 中</span>';
      case 1: return '<span style="color: #70a1ff;">🔵 低</span>';
      default: return '<span style="color: var(--text-muted);">-</span>';
    }
  }

  function formatDateTime(dateStr) {
    if (!dateStr) return '-';
    const date = new Date(dateStr);
    return date.toLocaleString('ja-JP', {
      month: '2-digit',
      day: '2-digit',
      hour: '2-digit',
      minute: '2-digit'
    });
  }

  function isOverdue(deadline) {
    if (!deadline) return false;
    return new Date(deadline) < new Date();
  }

  function matchesDeadlineFilter(deadline, filter) {
    if (!filter || !deadline) return true;

    const now = new Date();
    const deadlineDate = new Date(deadline);

    switch(filter) {
      case 'today':
        return deadlineDate.toDateString() === now.toDateString();
      case 'week':
        const weekFromNow = new Date(now.getTime() + 7 * 24 * 60 * 60 * 1000);
        return deadlineDate <= weekFromNow;
      case 'month':
        const monthFromNow = new Date(now.getTime() + 30 * 24 * 60 * 60 * 1000);
        return deadlineDate <= monthFromNow;
      case 'overdue':
        return deadlineDate < now;
      default:
        return true;
    }
  }

  function renderNotifications(notifications) {
    if (!notifications || notifications.length === 0) {
      tbody.innerHTML = '';
      emptyMessage.style.display = 'block';
      return;
    }

    emptyMessage.style.display = 'none';

    tbody.innerHTML = notifications.map(notification => {
      const isUnread = !notification.既読フラグ;
      const overdueClass = isOverdue(notification.期限日時) ? 'style="background: rgba(255, 107, 107, 0.05);"' : '';

      return `
        <tr data-id="${notification.通知履歴ID}" ${overdueClass} ${isUnread ? 'style="font-weight: 500; background: rgba(255,255,255,0.02);"' : ''}>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text); border-bottom: 1px solid rgba(255,255,255,0.05);">
            ${formatDateTime(notification.送信日時)}
            ${isUnread ? '<span style="color: #ff4757; margin-left: 4px;">●</span>' : ''}
          </td>
          <td style="padding: 6px 10px; font-size: 13px; border-bottom: 1px solid rgba(255,255,255,0.05);">
            <a href="#" class="document-link" data-document-id="${notification.申請書類ID}" style="color: var(--primary); text-decoration: none; cursor: pointer;">
              ${notification.通知タイトル || '申請書類'}
            </a>
          </td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text); border-bottom: 1px solid rgba(255,255,255,0.05);">
            ${notification.申請者名 || '-'}
          </td>
          <td style="padding: 6px 10px; font-size: 13px; border-bottom: 1px solid rgba(255,255,255,0.05);">
            ${getPriorityIcon(notification.優先度)}
          </td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text); border-bottom: 1px solid rgba(255,255,255,0.05);">
            ${formatDateTime(notification.期限日時)}
            ${isOverdue(notification.期限日時) ? '<span style="color: #ff4757; margin-left: 4px; font-size: 11px;">期限超過</span>' : ''}
          </td>
          <td style="padding: 6px 10px; font-size: 13px; border-bottom: 1px solid rgba(255,255,255,0.05);">
            <button class="action-btn" onclick="window.showScreen('scr-1779422434952')" style="background: var(--primary); color: #fff; border: none; padding: 4px 8px; border-radius: 4px; font-size: 12px; cursor: pointer;">案件詳細</button>
          </td>
        </tr>
      `;
    }).join('');

    // 未読件数の更新
    updateUnreadBadge(notifications);

    // 遅延警告の更新
    updateDelayAlert(notifications);
  }

  function updateUnreadBadge(notifications) {
    const unreadCount = notifications.filter(n => !n.既読フラグ).length;
    if (unreadCount > 0) {
      unreadBadge.textContent = unreadCount;
      unreadBadge.style.display = 'block';
    } else {
      unreadBadge.style.display = 'none';
    }
  }

  function updateDelayAlert(notifications) {
    const overdueNotifications = notifications.filter(n => isOverdue(n.期限日時));

    if (overdueNotifications.length > 0) {
      delayAlert.style.display = 'block';
      delayDetails.textContent = `${overdueNotifications.length}件の案件が期限を過ぎています`;
    } else {
      delayAlert.style.display = 'none';
    }
  }

  function populateApplicantFilter(notifications) {
    const applicants = [...new Set(notifications.map(n => n.申請者名).filter(name => name))];
    applicantFilter.innerHTML = '<option value="">すべて</option>' + 
      applicants.map(name => `<option value="${name}">${name}</option>`).join('');
  }

  function applyFilters() {
    let filtered = allNotifications;

    if (currentFilters.priority) {
      filtered = filtered.filter(n => n.優先度 == currentFilters.priority);
    }

    if (currentFilters.documentType) {
      filtered = filtered.filter(n => n.通知種別 === currentFilters.documentType || n.通知タイトル?.includes(currentFilters.documentType));
    }

    if (currentFilters.applicant) {
      filtered = filtered.filter(n => n.申請者名 === currentFilters.applicant);
    }

    if (currentFilters.deadline) {
      filtered = filtered.filter(n => matchesDeadlineFilter(n.期限日時, currentFilters.deadline));
    }

    renderNotifications(filtered);
  }

  async function loadNotifications() {
    try {
      const notifications = await window.aivicApi.list(5); // 通知履歴テーブル
      if (notifications) {
        // 承認待ちの通知のみフィルタ
        allNotifications = notifications.filter(n => 
          n.通知種別 === '承認依頼' && n.送信状態 === '送信完了'
        );

        // 申請者フィルターの選択肢を更新
        populateApplicantFilter(allNotifications);

        // 初期表示
        renderNotifications(allNotifications);
      }
    } catch (error) {
      console.error('通知データの取得に失敗しました:', error);
      emptyMessage.textContent = 'データの取得に失敗しました。再度お試しください。';
      emptyMessage.style.display = 'block';
    }
  }

  // 初期データ表示
  if (tables[5] && tables[5].records) {
    allNotifications = tables[5].records.filter(n => 
      n.通知種別 === '承認依頼' && n.送信状態 === '送信完了'
    );
    populateApplicantFilter(allNotifications);
    renderNotifications(allNotifications);
  }

  // 最新データを取得
  loadNotifications();

  // フィルター適用
  container.querySelector('#btn-filter').addEventListener('click', () => {
    currentFilters.priority = container.querySelector('#priority-filter').value;
    currentFilters.documentType = container.querySelector('#document-type-filter').value;
    currentFilters.applicant = container.querySelector('#applicant-filter').value;
    currentFilters.deadline = container.querySelector('#deadline-filter').value;

    applyFilters();
  });

  // フィルタークリア
  container.querySelector('#btn-clear-filter').addEventListener('click', () => {
    container.querySelector('#priority-filter').value = '';
    container.querySelector('#document-type-filter').value = '';
    container.querySelector('#applicant-filter').value = '';
    container.querySelector('#deadline-filter').value = '';

    currentFilters = { priority: '', documentType: '', applicant: '', deadline: '' };
    renderNotifications(allNotifications);
  });

  // 更新ボタン
  container.querySelector('#btn-refresh').addEventListener('click', () => {
    loadNotifications();
  });

  // 申請書類リンククリック
  container.addEventListener('click', async (e) => {
    const documentLink = e.target.closest('.document-link');
    if (documentLink) {
      e.preventDefault();
      const documentId = documentLink.dataset.documentId;

      if (!documentId || documentId === 'undefined') {
        alert('申請書類が見つかりません');
        return;
      }

      try {
        // 通知を既読にする
        const notificationRow = documentLink.closest('tr');
        const notificationId = notificationRow.dataset.id;

        if (notificationId) {
          await window.aivicApi.update(5, notificationId, { 
            既読フラグ: true, 
            既読日時: new Date().toISOString() 
          });

          // 画面を更新
          loadNotifications();
        }

        // 申請書類詳細画面に遷移
        window.showScreen('scr-1779422434952');
      } catch (error) {
        console.error('申請書類の表示に失敗しました:', error);
        alert('申請書類の表示に失敗しました');
      }
    }
  });
}

function(container, apiUrl, tables) {
  // 現在の申請書類ID（実際の実装では URL パラメータから取得）
  let currentApplicationId = null;

  // 初期データの設定
  function initializeData() {
    const applications = tables[1]?.records || [];
    const users = tables[0]?.records || [];
    const approvalHistory = tables[5]?.records || [];

    if (applications.length > 0) {
      currentApplicationId = applications[0].申請書類ID;
      const app = applications[0];
      const applicant = users.find(u => u.ユーザーID === app.申請者ID);

      // 申請書類情報の表示
      container.querySelector('#applicant-name').textContent = applicant?.ユーザー名 || '不明';
      container.querySelector('#document-type').textContent = app.申請種別 || '';
      container.querySelector('#application-date').textContent = app.作成日時 || '';
      container.querySelector('#application-amount').textContent = app.申請金額 ? `¥${app.申請金額.toLocaleString()}` : '';
      container.querySelector('#current-step').textContent = `${app.承認段階}段階目`;
      container.querySelector('#approval-status').textContent = app.承認状態 || '';
      container.querySelector('#application-content').textContent = app.申請内容 || '';
    }
  }

  // 承認履歴の表示
  function renderApprovalHistory() {
    const historyContainer = container.querySelector('#approval-history');
    const approvalHistory = tables[5]?.records || [];
    const users = tables[0]?.records || [];

    if (approvalHistory.length === 0) {
      historyContainer.innerHTML = '<div style="font-size: 12px; color: var(--text-muted); text-align: center; padding: 20px;">承認履歴はありません</div>';
      return;
    }

    const historyHtml = approvalHistory.map(history => {
      const approver = users.find(u => u.ユーザーID === history.承認者ID);
      const statusColor = history.承認結果 === '承認' ? '#28a745' : 
                         history.承認結果 === '差戻し' ? '#ff6a00' : 
                         history.承認結果 === '却下' ? '#dc3545' : 'var(--primary)';

      return `
        <div style="border-left: 3px solid ${statusColor}; padding-left: 8px; margin-bottom: 12px;">
          <div style="font-size: 12px; color: var(--text); font-weight: 500;">${history.承認結果}</div>
          <div style="font-size: 11px; color: var(--text-muted);">${approver?.ユーザー名 || '不明'}</div>
          <div style="font-size: 11px; color: var(--text-muted);">${history.承認日時 || ''}</div>
          ${history.承認コメント ? `<div style="font-size: 11px; color: var(--text); margin-top: 4px;">${history.承認コメント}</div>` : ''}
        </div>
      `;
    }).join('');

    historyContainer.innerHTML = historyHtml;
  }

  // 添付ファイル表示の更新
  function updateAttachmentDisplay() {
    const applications = tables[1]?.records || [];
    const currentApp = applications.find(app => app.申請書類ID === currentApplicationId);
    const attachmentList = container.querySelector('#attachment-list');

    if (!currentApp || !currentApp.添付ファイル有無) {
      attachmentList.innerHTML = '<div style="font-size: 12px; color: var(--text-muted); text-align: center; padding: 20px;">添付ファイルはありません</div>';
    }
  }

  // コメント文字数カウント
  function setupCommentCounter() {
    const commentTextarea = container.querySelector('#approval-comment');
    const countDisplay = container.querySelector('#comment-count');

    commentTextarea.addEventListener('input', function() {
      const count = this.value.length;
      countDisplay.textContent = count;

      if (count > 500) {
        this.value = this.value.substring(0, 500);
        countDisplay.textContent = '500';
      }
    });
  }

  // ファイルプレビュー機能
  function setupFilePreview() {
    const modal = container.querySelector('#file-preview-modal');
    const closeBtn = container.querySelector('#close-preview');
    const previewContent = container.querySelector('#preview-content');

    container.addEventListener('click', function(e) {
      if (e.target.matches('[data-testid="preview-button"]')) {
        previewContent.innerHTML = '<div style="padding: 40px; font-size: 14px;">ファイルプレビュー機能（実装中）</div>';
        modal.style.display = 'block';
      }
    });

    closeBtn.addEventListener('click', function() {
      modal.style.display = 'none';
    });

    modal.addEventListener('click', function(e) {
      if (e.target === modal) {
        modal.style.display = 'none';
      }
    });
  }

  // 確認ダイアログ
  function showConfirmDialog(message) {
    return new Promise((resolve) => {
      const dialog = container.querySelector('#confirm-dialog');
      const messageEl = container.querySelector('#confirm-message');
      const okBtn = container.querySelector('#confirm-ok');
      const cancelBtn = container.querySelector('#confirm-cancel');

      messageEl.textContent = message;
      dialog.style.display = 'block';

      const handleOk = () => {
        dialog.style.display = 'none';
        okBtn.removeEventListener('click', handleOk);
        cancelBtn.removeEventListener('click', handleCancel);
        resolve(true);
      };

      const handleCancel = () => {
        dialog.style.display = 'none';
        okBtn.removeEventListener('click', handleOk);
        cancelBtn.removeEventListener('click', handleCancel);
        resolve(false);
      };

      okBtn.addEventListener('click', handleOk);
      cancelBtn.addEventListener('click', handleCancel);
    });
  }

  // バリデーション
  function validateDecision() {
    const decision = container.querySelector('input[name="decision"]:checked');
    const comment = container.querySelector('#approval-comment').value.trim();

    if (!decision) {
      alert('承認判断を選択してください。');
      return false;
    }

    if ((decision.value === 'reject' || decision.value === 'deny') && comment.length < 10) {
      alert('差戻し・却下の場合は10文字以上のコメントが必要です。');
      return false;
    }

    if (comment.length > 500) {
      alert('コメントは500文字以内で入力してください。');
      return false;
    }

    return true;
  }

  // 承認判断の実行
  async function executeDecision() {
    if (!validateDecision()) return;

    const decision = container.querySelector('input[name="decision"]:checked').value;
    const comment = container.querySelector('#approval-comment').value.trim();
    const isConditional = container.querySelector('#conditional-approval').checked;

    const decisionText = decision === 'approve' ? '承認' : 
                        decision === 'reject' ? '差戻し' : '却下';
    const conditionalText = isConditional ? '（条件付き）' : '';

    const confirmed = await showConfirmDialog(`この申請を「${decisionText}${conditionalText}」で処理しますか？`);
    if (!confirmed) return;

    try {
      // 承認履歴の保存
      const historyData = {
        申請書類ID: currentApplicationId,
        承認者ID: 'current-user-id', // 実際の実装では現在のユーザーIDを使用
        承認結果: decisionText,
        承認コメント: comment,
        承認日時: new Date().toISOString(),
        代理承認フラグ: false
      };

      const savedHistory = await window.aivicApi.save(5, historyData);

      if (savedHistory) {
        // 申請書類のステータス更新
        const updateData = {
          承認状態: isConditional ? `条件付き${decisionText}` : decisionText,
          最終承認日時: new Date().toISOString()
        };

        await window.aivicApi.update(1, currentApplicationId, updateData);

        alert('承認判断を正常に処理しました。');
        window.showScreen("scr-1779422470870"); // 結果通知処理画面へ
      } else {
        alert('承認判断の保存に失敗しました。');
      }
    } catch (error) {
      console.error('承認判断処理エラー:', error);
      alert('承認判断の処理中にエラーが発生しました。');
    }
  }

  // イベントリスナーの設定
  function setupEventListeners() {
    // 判断確定ボタン
    container.querySelector('#submit-decision').addEventListener('click', executeDecision);

    // 戻るボタン
    container.querySelector('[data-testid="back-button"]').addEventListener('click', function() {
      window.showScreen("scr-1779422434952"); // 申請書類確認画面へ
    });

    // 条件付き承認チェックボックスの制御
    container.querySelector('#conditional-approval').addEventListener('change', function() {
      const approveRadio = container.querySelector('input[name="decision"][value="approve"]');
      if (this.checked && !approveRadio.checked) {
        approveRadio.checked = true;
      }
    });

    // 承認以外を選択した場合は条件付き承認を無効化
    container.querySelectorAll('input[name="decision"]').forEach(radio => {
      radio.addEventListener('change', function() {
        const conditionalCheckbox = container.querySelector('#conditional-approval');
        if (this.value !== 'approve') {
          conditionalCheckbox.checked = false;
        }
      });
    });
  }

  // 初期化処理
  initializeData();
  renderApprovalHistory();
  updateAttachmentDisplay();
  setupCommentCounter();
  setupFilePreview();
  setupEventListeners();
}

function(container, apiUrl, tables) {
  let editingId = null;

  // 1. 再描画関数の定義
  function renderRows(rows) {
    const tbody = container.querySelector('#criteria-tbody');
    tbody.innerHTML = rows.map(r => `
      <tr data-id="${r.id}">
        <td>${r.分類基準名 || ''}</td>
        <td>${r.文書種別 || ''}</td>
        <td>${getRelevanceText(r.補助金関連度)}</td>
        <td>${r.処理ルート || ''}</td>
        <td>${r.優先度 || ''}</td>
        <td>
          <span style="padding: 2px 6px; border-radius: 4px; font-size: 11px; ${r.有効フラグ ? 'background: rgba(34, 197, 94, 0.2); color: #22c55e;' : 'background: rgba(239, 68, 68, 0.2); color: #ef4444;'}">
            ${r.有効フラグ ? '有効' : '無効'}
          </span>
        </td>
        <td>${r.適用開始日 ? new Date(r.適用開始日).toLocaleDateString('ja-JP') : ''}</td>
        <td>
          <button class="action-btn secondary edit-btn" data-id="${r.id}" style="margin-right: 4px;">編集</button>
          <button class="action-btn secondary delete-btn" data-id="${r.id}">削除</button>
        </td>
      </tr>
    `).join('');
  }

  function getRelevanceText(level) {
    switch(level) {
      case 1: return '低';
      case 2: return '中';
      case 3: return '高';
      default: return '';
    }
  }

  // 2. 初期データ読み込み
  window.aivicApi.list(0).then(rows => {
    if (rows) renderRows(rows);
  });

  // 3. 検索機能
  container.querySelector('#btn-search').addEventListener('click', async () => {
    const keyword = container.querySelector('#input-search').value;
    const statusFilter = container.querySelector('#filter-status').value;

    const rows = await window.aivicApi.list(0);
    if (!rows) return;

    const filtered = rows.filter(r => {
      const matchKeyword = !keyword || (r.分類基準名 && r.分類基準名.includes(keyword));
      const matchStatus = !statusFilter || r.有効フラグ.toString() === statusFilter;
      return matchKeyword && matchStatus;
    });

    renderRows(filtered);
  });

  // 4. CSVエクスポート
  container.querySelector('#btn-csv-export').addEventListener('click', async () => {
    const rows = await window.aivicApi.list(0);
    if (!rows) return;

    const headers = ['分類基準名', '文書種別', '補助金関連度', 'キーワード条件', '処理ルート', '優先度', '有効フラグ', '適用開始日', '適用終了日'];
    const csvContent = '\uFEFF' + [
      headers.join(','),
      ...rows.map(r => [
        `"${r.分類基準名 || ''}"`,
        `"${r.文書種別 || ''}"`,
        getRelevanceText(r.補助金関連度),
        `"${r.キーワード条件 || ''}"`,
        `"${r.処理ルート || ''}"`,
        r.優先度 || '',
        r.有効フラグ ? '有効' : '無効',
        r.適用開始日 ? new Date(r.適用開始日).toLocaleDateString('ja-JP') : '',
        r.適用終了日 ? new Date(r.適用終了日).toLocaleDateString('ja-JP') : ''
      ].join(','))
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = '分類基準一覧.csv';
    link.click();
  });

  // 5. モーダル制御
  const modal = container.querySelector('#criteria-modal');
  const form = container.querySelector('#criteria-form');

  function openModal(isEdit = false, data = null) {
    editingId = isEdit ? data.id : null;
    container.querySelector('#modal-title').textContent = isEdit ? '分類基準編集' : '新規分類基準作成';

    if (isEdit && data) {
      container.querySelector('#input-name').value = data.分類基準名 || '';
      container.querySelector('#input-document-type').value = data.文書種別 || '';
      container.querySelector(`input[name="subsidy-relevance"][value="${data.補助金関連度}"]`).checked = true;
      container.querySelector('#input-keywords').value = data.キーワード条件 || '';
      container.querySelector('#input-route').value = data.処理ルート || '';
      container.querySelector('#input-priority').value = data.優先度 || 500;
      container.querySelector('#priority-value').textContent = data.優先度 || 500;
      container.querySelector('#input-start-date').value = data.適用開始日 ? data.適用開始日.split('T')[0] : '';
      container.querySelector('#input-end-date').value = data.適用終了日 ? data.適用終了日.split('T')[0] : '';
      container.querySelector('#input-active').checked = data.有効フラグ;
    } else {
      form.reset();
      container.querySelector('#input-priority').value = 500;
      container.querySelector('#priority-value').textContent = '500';
      container.querySelector('#input-active').checked = true;
      // 適用開始日を今日に設定
      const today = new Date().toISOString().split('T')[0];
      container.querySelector('#input-start-date').value = today;
    }

    modal.style.display = 'block';
  }

  function closeModal() {
    modal.style.display = 'none';
    container.querySelector('#preview-area').style.display = 'none';
    editingId = null;
  }

  // 6. 新規作成ボタン
  container.querySelector('#btn-create').addEventListener('click', () => {
    openModal(false);
  });

  // 7. モーダル閉じる
  container.querySelector('#btn-close-modal').addEventListener('click', closeModal);
  container.querySelector('#btn-cancel').addEventListener('click', closeModal);

  // 8. 優先度スライダー
  container.querySelector('#input-priority').addEventListener('input', (e) => {
    container.querySelector('#priority-value').textContent = e.target.value;
  });

  // 9. 条件プレビュー
  container.querySelector('#btn-preview').addEventListener('click', () => {
    const name = container.querySelector('#input-name').value;
    const docType = container.querySelector('#input-document-type').value;
    const relevance = container.querySelector('input[name="subsidy-relevance"]:checked')?.value;
    const keywords = container.querySelector('#input-keywords').value;
    const route = container.querySelector('#input-route').value;
    const priority = container.querySelector('#input-priority').value;
    const startDate = container.querySelector('#input-start-date').value;
    const endDate = container.querySelector('#input-end-date').value;
    const active = container.querySelector('#input-active').checked;

    const previewContent = `
      <div><strong>分類基準名:</strong> ${name}</div>
      <div><strong>文書種別:</strong> ${docType}</div>
      <div><strong>補助金関連度:</strong> ${getRelevanceText(parseInt(relevance))}</div>
      <div><strong>キーワード条件:</strong> ${keywords}</div>
      <div><strong>処理ルート:</strong> ${route}</div>
      <div><strong>優先度:</strong> ${priority}</div>
      <div><strong>適用期間:</strong> ${startDate} ～ ${endDate || '無期限'}</div>
      <div><strong>状態:</strong> ${active ? '有効' : '無効'}</div>
    `;

    container.querySelector('#preview-content').innerHTML = previewContent;
    container.querySelector('#preview-area').style.display = 'block';
  });

  // 10. フォーム送信
  form.addEventListener('submit', async (e) => {
    e.preventDefault();

    const name = container.querySelector('#input-name').value.trim();
    const docType = container.querySelector('#input-document-type').value;
    const relevance = container.querySelector('input[name="subsidy-relevance"]:checked')?.value;
    const keywords = container.querySelector('#input-keywords').value.trim();
    const route = container.querySelector('#input-route').value;
    const priority = parseInt(container.querySelector('#input-priority').value);
    const startDate = container.querySelector('#input-start-date').value;
    const endDate = container.querySelector('#input-end-date').value;
    const active = container.querySelector('#input-active').checked;

    // バリデーション
    if (!name) {
      alert('分類基準名を入力してください。');
      return;
    }
    if (!docType) {
      alert('文書種別を選択してください。');
      return;
    }
    if (!relevance) {
      alert('補助金関連度を選択してください。');
      return;
    }
    if (!keywords) {
      alert('キーワード条件を入力してください。');
      return;
    }
    if (!route) {
      alert('処理ルートを選択してください。');
      return;
    }
    if (!startDate) {
      alert('適用開始日を入力してください。');
      return;
    }
    if (endDate && new Date(startDate) > new Date(endDate)) {
      alert('適用開始日は終了日より前の日付を設定してください。');
      return;
    }
    if (new Date(startDate) < new Date().setHours(0,0,0,0)) {
      alert('適用開始日は本日以降の日付を設定してください。');
      return;
    }

    // 重複チェック
    const existingRows = await window.aivicApi.list(0);
    if (existingRows) {
      const duplicate = existingRows.find(r => r.分類基準名 === name && r.id !== editingId);
      if (duplicate) {
        alert('同じ分類基準名が既に存在します。');
        return;
      }
    }

    const data = {
      分類基準名: name,
      文書種別: docType,
      補助金関連度: parseInt(relevance),
      キーワード条件: keywords,
      処理ルート: route,
      優先度: priority,
      適用開始日: startDate,
      適用終了日: endDate || null,
      有効フラグ: active,
      作成日時: new Date().toISOString(),
      更新日時: new Date().toISOString()
    };

    let result;
    if (editingId) {
      result = await window.aivicApi.update(0, editingId, data);
    } else {
      result = await window.aivicApi.save(0, data);
    }

    if (result) {
      alert('分類基準を保存しました。');
      closeModal();
      const rows = await window.aivicApi.list(0);
      if (rows) renderRows(rows);
    }
  });

  // 11. 行レベル操作（編集・削除）
  container.addEventListener('click', async (e) => {
    const editBtn = e.target.closest('.edit-btn');
    const deleteBtn = e.target.closest('.delete-btn');

    if (editBtn) {
      const id = editBtn.dataset.id;
      const rows = await window.aivicApi.list(0);
      if (rows) {
        const data = rows.find(r => r.id === id);
        if (data) {
          openModal(true, data);
        }
      }
    }

    if (deleteBtn) {
      if (!confirm('この分類基準を削除しますか？')) return;

      const id = deleteBtn.dataset.id;
      const result = await window.aivicApi.delete(0, id);
      if (result !== null) {
        alert('分類基準を削除しました。');
        const rows = await window.aivicApi.list(0);
        if (rows) renderRows(rows);
      }
    }
  });
}

function(container, apiUrl, tables) {
  let currentRouteId = null;
  let approvalSteps = [];

  // エラー・成功メッセージ表示関数
  function showError(message) {
    const errorEl = container.querySelector('#error-message');
    const successEl = container.querySelector('#success-message');
    successEl.style.display = 'none';
    errorEl.textContent = message;
    errorEl.style.display = 'block';
    setTimeout(() => errorEl.style.display = 'none', 5000);
  }

  function showSuccess(message) {
    const errorEl = container.querySelector('#error-message');
    const successEl = container.querySelector('#success-message');
    errorEl.style.display = 'none';
    successEl.textContent = message;
    successEl.style.display = 'block';
    setTimeout(() => successEl.style.display = 'none', 3000);
  }

  // 承認ステップテーブル再描画
  function renderApprovalSteps() {
    const tbody = container.querySelector('#approval-steps-tbody');
    tbody.innerHTML = approvalSteps.map((step, index) => `
      <tr data-step="${index + 1}">
        <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">
          <button class="move-up" style="background: transparent; border: 1px solid rgba(255,255,255,0.18); padding: 2px 6px; margin-right: 4px; border-radius: 4px; font-size: 11px; cursor: pointer; color: var(--text);" ${index === 0 ? 'disabled' : ''}>↑</button>
          <span>${index + 1}</span>
          <button class="move-down" style="background: transparent; border: 1px solid rgba(255,255,255,0.18); padding: 2px 6px; margin-left: 4px; border-radius: 4px; font-size: 11px; cursor: pointer; color: var(--text);" ${index === approvalSteps.length - 1 ? 'disabled' : ''}>↓</button>
        </td>
        <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${step.approver || ''}</td>
        <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${step.position || ''}</td>
        <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">
          <input type="checkbox" ${step.required ? 'checked' : ''} style="accent-color: var(--primary);" data-step-index="${index}">
        </td>
        <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">
          <button class="delete-step action-btn secondary" data-step-index="${index}" style="background: transparent; color: var(--text); border: 1px solid rgba(255,255,255,0.18); padding: 4px 8px; border-radius: 4px; font-size: 11px; cursor: pointer;">削除</button>
        </td>
      </tr>
    `).join('');
  }

  // 初期データ読み込み
  async function loadRouteData() {
    try {
      const routes = await window.aivicApi.list(7); // 処理ルートテーブル
      if (routes && routes.length > 0) {
        const route = routes[0]; // 最初のルートを編集対象とする
        currentRouteId = route.id;

        container.querySelector('#route-id').value = route.id || '';
        container.querySelector('#route-name').value = route.申請書類ID || '';
        container.querySelector('#document-type').value = route.承認フロー定義ID || '';
        container.querySelector('#subsidy-level').value = route.優先度 || '';
        container.querySelector('#approval-flow').value = route.承認フロー定義ID || '';
        container.querySelector('#required-approval').checked = route.自動処理フラグ || false;
        container.querySelector('#proxy-approval').checked = route.自動処理フラグ || false;
        container.querySelector('#delay-hours').value = 24;

        // 承認ステップの初期データ
        approvalSteps = [
          { approver: '田中部長', position: '部長', required: true },
          { approver: '佐藤課長', position: '課長', required: false }
        ];
        renderApprovalSteps();
      }
    } catch (error) {
      console.error('データ読み込みエラー:', error);
    }
  }

  // バリデーション
  function validateForm() {
    const routeName = container.querySelector('#route-name').value.trim();
    const documentType = container.querySelector('#document-type').value;
    const delayHours = container.querySelector('#delay-hours').value;

    if (!routeName) {
      showError('処理ルート名は必須項目です');
      return false;
    }

    if (routeName.length > 100) {
      showError('処理ルート名は100文字以内で入力してください');
      return false;
    }

    if (!documentType) {
      showError('文書種別を選択してください');
      return false;
    }

    if (approvalSteps.length === 0) {
      showError('承認者を設定してください');
      return false;
    }

    const requiredApprovers = approvalSteps.filter(step => step.required);
    if (requiredApprovers.length === 0) {
      showError('必須承認者が設定されていません');
      return false;
    }

    if (delayHours && (isNaN(delayHours) || parseInt(delayHours) < 0)) {
      showError('遅延検知設定には正の数値を入力してください');
      return false;
    }

    return true;
  }

  // 更新ボタンクリック
  container.querySelector('#btn-update').addEventListener('click', async () => {
    if (!validateForm()) return;

    if (!confirm('処理ルートを更新しますか？')) return;

    try {
      const updateData = {
        申請書類ID: container.querySelector('#route-name').value.trim(),
        承認フロー定義ID: container.querySelector('#document-type').value,
        優先度: parseInt(container.querySelector('#subsidy-level').value) || 2,
        自動処理フラグ: container.querySelector('#required-approval').checked,
        備考: `承認ステップ数: ${approvalSteps.length}, 代理承認: ${container.querySelector('#proxy-approval').checked ? '許可' : '不許可'}`,
        更新日時: new Date().toISOString(),
        更新者ID: 'current-user-id'
      };

      const result = await window.aivicApi.update(7, currentRouteId, updateData);
      if (result) {
        showSuccess('処理ルートが正常に更新されました');
        setTimeout(() => {
          window.showScreen('scr-1779422591281'); // 処理ルート設定画面に戻る
        }, 1500);
      } else {
        showError('更新に失敗しました');
      }
    } catch (error) {
      console.error('更新エラー:', error);
      showError('ネットワークエラーが発生しました');
    }
  });

  // キャンセルボタン
  container.querySelector('#btn-cancel').addEventListener('click', () => {
    window.showScreen('scr-1779422591281'); // 処理ルート設定画面に戻る
  });

  // 承認者追加ボタン
  container.querySelector('#add-approver').addEventListener('click', () => {
    container.querySelector('#add-approver-modal').style.display = 'block';
  });

  // モーダル関連
  container.querySelector('#modal-cancel').addEventListener('click', () => {
    container.querySelector('#add-approver-modal').style.display = 'none';
  });

  container.querySelector('#modal-add').addEventListener('click', () => {
    const approver = container.querySelector('#modal-approver').value;
    const position = container.querySelector('#modal-position').value.trim();
    const required = container.querySelector('#modal-required').checked;

    if (!approver) {
      showError('承認者を選択してください');
      return;
    }

    const approverNames = {
      'yamada': '山田取締役',
      'suzuki': '鈴木部長', 
      'watanabe': '渡辺課長',
      'ito': '伊藤主任'
    };

    approvalSteps.push({
      approver: approverNames[approver] || approver,
      position: position || '未設定',
      required: required
    });

    renderApprovalSteps();
    container.querySelector('#add-approver-modal').style.display = 'none';

    // フォームリセット
    container.querySelector('#modal-approver').value = '';
    container.querySelector('#modal-position').value = '';
    container.querySelector('#modal-required').checked = false;
  });

  // テーブル内イベント処理
  container.addEventListener('click', (e) => {
    // 削除ボタン
    const deleteBtn = e.target.closest('.delete-step');
    if (deleteBtn) {
      const index = parseInt(deleteBtn.dataset.stepIndex);
      if (confirm('この承認者を削除しますか？')) {
        approvalSteps.splice(index, 1);
        renderApprovalSteps();
      }
      return;
    }

    // 上移動ボタン
    const moveUpBtn = e.target.closest('.move-up');
    if (moveUpBtn && !moveUpBtn.disabled) {
      const row = moveUpBtn.closest('tr');
      const index = parseInt(row.dataset.step) - 1;
      if (index > 0) {
        [approvalSteps[index], approvalSteps[index - 1]] = [approvalSteps[index - 1], approvalSteps[index]];
        renderApprovalSteps();
      }
      return;
    }

    // 下移動ボタン
    const moveDownBtn = e.target.closest('.move-down');
    if (moveDownBtn && !moveDownBtn.disabled) {
      const row = moveDownBtn.closest('tr');
      const index = parseInt(row.dataset.step) - 1;
      if (index < approvalSteps.length - 1) {
        [approvalSteps[index], approvalSteps[index + 1]] = [approvalSteps[index + 1], approvalSteps[index]];
        renderApprovalSteps();
      }
      return;
    }
  });

  // 必須チェックボックス変更
  container.addEventListener('change', (e) => {
    if (e.target.type === 'checkbox' && e.target.dataset.stepIndex !== undefined) {
      const index = parseInt(e.target.dataset.stepIndex);
      approvalSteps[index].required = e.target.checked;
    }
  });

  // 初期データ読み込み実行
  loadRouteData();
}

function(container, apiUrl, tables) {
  let currentFile = null;
  let currentJudgment = null;

  // DOM要素の取得
  const uploadArea = container.querySelector('#upload-area');
  const fileInput = container.querySelector('#file-input');
  const uploadPlaceholder = container.querySelector('#upload-placeholder');
  const uploadPreview = container.querySelector('#upload-preview');
  const fileName = container.querySelector('#file-name');
  const fileSize = container.querySelector('#file-size');
  const autoJudgmentResult = container.querySelector('#auto-judgment-result');
  const accuracyBar = container.querySelector('#accuracy-bar');
  const accuracyText = container.querySelector('#accuracy-text');
  const subsidyScoreBar = container.querySelector('#subsidy-score-bar');
  const subsidyScoreText = container.querySelector('#subsidy-score-text');
  const manualDocumentType = container.querySelector('#manual-document-type');
  const documentPreview = container.querySelector('#document-preview');
  const historyTbody = container.querySelector('#history-tbody');
  const errorMessage = container.querySelector('#error-message');
  const successMessage = container.querySelector('#success-message');

  // ボタン要素
  const btnFileSelect = container.querySelector('#btn-file-select');
  const btnExecuteJudgment = container.querySelector('#btn-execute-judgment');
  const btnReJudgment = container.querySelector('#btn-re-judgment');
  const btnConfirmResult = container.querySelector('#btn-confirm-result');
  const btnApprovalFlow = container.querySelector('#btn-approval-flow');
  const btnMasterRef = container.querySelector('#btn-master-ref');
  const btnDigitization = container.querySelector('#btn-digitization');

  // タブ機能
  const tabBtns = container.querySelectorAll('.tab-btn');
  const tabPanels = container.querySelectorAll('.tab-panel');

  // エラー表示関数
  function showError(message) {
    errorMessage.textContent = message;
    errorMessage.style.display = 'block';
    successMessage.style.display = 'none';
    setTimeout(() => {
      errorMessage.style.display = 'none';
    }, 5000);
  }

  // 成功メッセージ表示関数
  function showSuccess(message) {
    successMessage.textContent = message;
    successMessage.style.display = 'block';
    errorMessage.style.display = 'none';
    setTimeout(() => {
      successMessage.style.display = 'none';
    }, 3000);
  }

  // ファイルサイズフォーマット関数
  function formatFileSize(bytes) {
    if (bytes === 0) return '0 Bytes';
    const k = 1024;
    const sizes = ['Bytes', 'KB', 'MB', 'GB'];
    const i = Math.floor(Math.log(bytes) / Math.log(k));
    return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + ' ' + sizes[i];
  }

  // ファイル検証関数
  function validateFile(file) {
    const maxSize = 10 * 1024 * 1024; // 10MB
    const allowedTypes = ['application/pdf', 'application/msword', 'application/vnd.openxmlformats-officedocument.wordprocessingml.document', 'application/vnd.ms-excel', 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'];

    if (file.size > maxSize) {
      return 'ファイルサイズが上限（10MB）を超えています。';
    }

    if (!allowedTypes.includes(file.type) && !file.name.match(/\.(pdf|doc|docx|xls|xlsx)$/i)) {
      return '対応していないファイル形式です。PDF、Word、Excel形式のファイルをアップロードしてください。';
    }

    return null;
  }

  // ファイル選択処理
  function handleFileSelect(file) {
    const error = validateFile(file);
    if (error) {
      showError(error);
      return;
    }

    currentFile = file;
    fileName.textContent = file.name;
    fileSize.textContent = formatFileSize(file.size);
    uploadPlaceholder.style.display = 'none';
    uploadPreview.style.display = 'block';

    btnExecuteJudgment.disabled = false;

    // プレビュー表示
    if (file.type === 'application/pdf') {
      documentPreview.innerHTML = '<div style="padding: 20px; text-align: center;"><div style="font-size: 48px; margin-bottom: 12px;">📄</div><div style="color: var(--text);">PDF: ' + file.name + '</div></div>';
    } else {
      documentPreview.innerHTML = '<div style="padding: 20px; text-align: center;"><div style="font-size: 48px; margin-bottom: 12px;">📄</div><div style="color: var(--text);">' + file.name + '</div><div style="color: var(--text-muted); font-size: 11px; margin-top: 8px;">プレビューはPDFファイルのみ対応</div></div>';
    }

    showSuccess('ファイルが正常にアップロードされました。');
  }

  // 文書種別判定実行
  async function executeJudgment() {
    if (!currentFile) {
      showError('ファイルを選択してください。');
      return;
    }

    btnExecuteJudgment.disabled = true;
    autoJudgmentResult.textContent = '判定中...';

    // シミュレート判定処理
    setTimeout(async () => {
      try {
        // ランダムな判定結果を生成（実際のAPIでは文書解析結果）
        const documentTypes = ['経費申請書', '休暇申請書', '購買申請書', '補助金申請書', '契約書類', 'その他'];
        const randomType = documentTypes[Math.floor(Math.random() * documentTypes.length)];
        const accuracy = Math.floor(Math.random() * 101);
        const subsidyScore = Math.floor(Math.random() * 101);

        currentJudgment = {
          documentType: randomType,
          accuracy: accuracy,
          subsidyScore: subsidyScore,
          timestamp: new Date()
        };

        // 結果表示更新
        autoJudgmentResult.textContent = randomType;
        accuracyBar.style.width = accuracy + '%';
        accuracyText.textContent = accuracy + '%';
        subsidyScoreBar.style.width = subsidyScore + '%';
        subsidyScoreText.textContent = subsidyScore;

        // 精度に応じた色変更
        if (accuracy >= 80) {
          accuracyBar.style.background = '#10b981';
        } else if (accuracy >= 60) {
          accuracyBar.style.background = '#f59e0b';
        } else {
          accuracyBar.style.background = '#ef4444';
        }

        btnExecuteJudgment.disabled = false;
        btnReJudgment.disabled = false;
        btnConfirmResult.disabled = false;

        // 履歴に追加
        await addJudgmentHistory(currentJudgment);

        showSuccess('文書種別判定が完了しました。');

      } catch (error) {
        showError('判定処理中にエラーが発生しました。');
        btnExecuteJudgment.disabled = false;
      }
    }, 2000);
  }

  // 判定履歴追加
  async function addJudgmentHistory(judgment) {
    const historyData = {
      申請書類ID: 'temp-' + Date.now(),
      判定日時: judgment.timestamp.toISOString(),
      文書種別: judgment.documentType,
      判定精度: judgment.accuracy,
      判定者ID: 'current-user',
      判定者名: '現在のユーザー'
    };

    try {
      await window.aivicApi.save(4, historyData); // 承認履歴テーブルに保存
      await loadJudgmentHistory();
    } catch (error) {
      console.error('履歴保存エラー:', error);
    }
  }

  // 判定履歴読み込み
  async function loadJudgmentHistory() {
    try {
      const histories = await window.aivicApi.list(4);
      if (histories && histories.length > 0) {
        historyTbody.innerHTML = histories.slice(-10).reverse().map(h => `
          <tr>
            <td style="padding: 6px 8px; font-size: 12px;">${new Date(h.判定日時 || h.承認日時).toLocaleString()}</td>
            <td style="padding: 6px 8px; font-size: 12px;">${h.文書種別 || h.承認結果 || '-'}</td>
            <td style="padding: 6px 8px; font-size: 12px;">${h.判定精度 || '-'}${h.判定精度 ? '%' : ''}</td>
            <td style="padding: 6px 8px; font-size: 12px;">${h.判定者名 || 'システム'}</td>
          </tr>
        `).join('');
      } else {
        historyTbody.innerHTML = '<tr><td colspan="4" style="padding: 20px; text-align: center; color: var(--text-muted); font-size: 13px;">履歴がありません</td></tr>';
      }
    } catch (error) {
      console.error('履歴読み込みエラー:', error);
    }
  }

  // イベントリスナー設定

  // ファイル選択ボタン
  btnFileSelect.addEventListener('click', () => {
    fileInput.click();
  });

  // ファイル入力変更
  fileInput.addEventListener('change', (e) => {
    const file = e.target.files[0];
    if (file) {
      handleFileSelect(file);
    }
  });

  // ドラッグ&ドロップ
  uploadArea.addEventListener('dragover', (e) => {
    e.preventDefault();
    uploadArea.style.borderColor = 'var(--primary)';
  });

  uploadArea.addEventListener('dragleave', (e) => {
    e.preventDefault();
    uploadArea.style.borderColor = 'rgba(255,255,255,0.18)';
  });

  uploadArea.addEventListener('drop', (e) => {
    e.preventDefault();
    uploadArea.style.borderColor = 'rgba(255,255,255,0.18)';
    const file = e.dataTransfer.files[0];
    if (file) {
      handleFileSelect(file);
    }
  });

  // 判定実行ボタン
  btnExecuteJudgment.addEventListener('click', executeJudgment);

  // 再判定ボタン
  btnReJudgment.addEventListener('click', executeJudgment);

  // 結果確定ボタン
  btnConfirmResult.addEventListener('click', async () => {
    if (!currentJudgment && !manualDocumentType.value) {
      showError('文書種別を選択してください。');
      return;
    }

    const finalType = manualDocumentType.value || currentJudgment?.documentType;
    if (!finalType) {
      showError('文書種別を選択してください。');
      return;
    }

    try {
      // 申請書類として保存
      const applicationData = {
        申請者ID: 'current-user',
        申請種別: finalType,
        申請タイトル: currentFile?.name || '文書種別判定結果',
        申請内容: `文書種別: ${finalType}`,
        承認状態: '申請中',
        承認段階: 1,
        緊急フラグ: false,
        添付ファイル有無: !!currentFile
      };

      await window.aivicApi.save(1, applicationData);
      showSuccess('判定結果が確定されました。承認フローが開始されます。');

      // フォームリセット
      currentFile = null;
      currentJudgment = null;
      fileInput.value = '';
      uploadPlaceholder.style.display = 'block';
      uploadPreview.style.display = 'none';
      autoJudgmentResult.textContent = '判定待ち';
      accuracyBar.style.width = '0%';
      accuracyText.textContent = '0%';
      subsidyScoreBar.style.width = '0%';
      subsidyScoreText.textContent = '0';
      manualDocumentType.value = '';
      documentPreview.innerHTML = '<div style="display: flex; align-items: center; justify-content: center; height: 100%; color: var(--text-muted); font-size: 13px;">文書を選択してください</div>';

      btnExecuteJudgment.disabled = true;
      btnReJudgment.disabled = true;
      btnConfirmResult.disabled = true;

    } catch (error) {
      showError('結果確定処理中にエラーが発生しました。');
    }
  });

  // 承認フロー確認ボタン
  btnApprovalFlow.addEventListener('click', () => {
    showSuccess('承認フロー確認画面に遷移します。');
  });

  // 文書種別マスタ参照ボタン
  btnMasterRef.addEventListener('click', () => {
    showSuccess('文書種別マスタ参照画面に遷移します。');
  });

  // 電子化可否判定ボタン
  btnDigitization.addEventListener('click', () => {
    window.showScreen("scr-1779422575885");
  });

  // タブ切り替え
  tabBtns.forEach(btn => {
    btn.addEventListener('click', () => {
      const targetTab = btn.dataset.tab;

      // タブボタンの状態更新
      tabBtns.forEach(b => {
        b.classList.remove('active');
        b.style.color = 'var(--text-muted)';
        b.style.borderBottomColor = 'transparent';
      });
      btn.classList.add('active');
      btn.style.color = 'var(--text)';
      btn.style.borderBottomColor = 'var(--primary)';

      // パネルの表示切り替え
      tabPanels.forEach(panel => {
        panel.style.display = 'none';
      });
      container.querySelector(`#${targetTab}-panel`).style.display = 'block';
    });
  });

  // 初期データ読み込み
  loadJudgmentHistory();
}

