function(container, apiUrl, tables) {
  const tbody = container.querySelector('#document-tbody');
  const errorMessage = container.querySelector('#error-message');
  const noResults = container.querySelector('#no-results');

  // ユーザーマスタから申請者・承認者名を取得するためのマップ
  const userMap = new Map();
  if (tables[0] && tables[0].records) {
    tables[0].records.forEach(user => {
      userMap.set(user.ユーザーID, user.ユーザー名);
    });
  }

  // 補助金関連度マスタからレベルを取得するためのマップ
  const subsidyMap = new Map();
  if (tables[9] && tables[9].records) {
    tables[9].records.forEach(subsidy => {
      subsidyMap.set(subsidy.補助金関連度ID, subsidy.補助金関連度名);
    });
  }

  function showError(message) {
    errorMessage.textContent = message;
    errorMessage.style.display = 'block';
    setTimeout(() => {
      errorMessage.style.display = 'none';
    }, 5000);
  }

  function formatDate(dateStr) {
    if (!dateStr) return '';
    const date = new Date(dateStr);
    return date.toLocaleDateString('ja-JP');
  }

  function getStatusBadge(status) {
    const colors = {
      '申請中': 'background: rgba(59, 130, 246, 0.1); color: #3b82f6; border: 1px solid rgba(59, 130, 246, 0.3);',
      '承認待ち': 'background: rgba(245, 158, 11, 0.1); color: #f59e0b; border: 1px solid rgba(245, 158, 11, 0.3);',
      '承認済': 'background: rgba(34, 197, 94, 0.1); color: #22c55e; border: 1px solid rgba(34, 197, 94, 0.3);',
      '却下': 'background: rgba(239, 68, 68, 0.1); color: #ef4444; border: 1px solid rgba(239, 68, 68, 0.3);',
      '差戻し': 'background: rgba(168, 85, 247, 0.1); color: #a855f7; border: 1px solid rgba(168, 85, 247, 0.3);',
      '取下げ': 'background: rgba(107, 114, 128, 0.1); color: #6b7280; border: 1px solid rgba(107, 114, 128, 0.3);'
    };
    const style = colors[status] || 'background: rgba(107, 114, 128, 0.1); color: #6b7280; border: 1px solid rgba(107, 114, 128, 0.3);';
    return `<span style="padding: 2px 6px; border-radius: 4px; font-size: 11px; font-weight: 500; ${style}">${status || ''}</span>`;
  }

  function renderRows(rows) {
    if (!rows || rows.length === 0) {
      tbody.innerHTML = '';
      noResults.style.display = 'block';
      return;
    }

    noResults.style.display = 'none';
    tbody.innerHTML = rows.map(row => {
      const applicantName = userMap.get(row.申請者ID) || '';
      const approverName = userMap.get(row.現在承認者ID) || '';
      const subsidyLevel = subsidyMap.get(row.補助金関連度ID) || '';

      return `
        <tr data-id="${row.申請書類ID}" style="border-bottom: 1px solid rgba(255,255,255,0.02);">
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">
            <a href="#" class="document-link" data-id="${row.申請書類ID}" style="color: var(--primary); text-decoration: none; cursor: pointer;">${row.申請書類ID?.substring(0, 8) || ''}</a>
          </td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${row.申請種別 || ''}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${row.申請タイトル || ''}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${applicantName}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${formatDate(row.作成日時)}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${getStatusBadge(row.承認状態)}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${approverName}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${subsidyLevel}</td>
        </tr>
      `;
    }).join('');
  }

  // 初期データ表示
  if (tables[1] && tables[1].records) {
    renderRows(tables[1].records);
  }

  // 検索機能
  async function performSearch() {
    try {
      const keyword = container.querySelector('#input-keyword').value.trim();
      const documentType = container.querySelector('#select-document-type').value;
      const approvalStatus = container.querySelector('#select-approval-status').value;
      const dateStart = container.querySelector('#input-date-start').value;
      const dateEnd = container.querySelector('#input-date-end').value;
      const applicant = container.querySelector('#input-applicant').value.trim();
      const approver = container.querySelector('#input-approver').value.trim();
      const processRoute = container.querySelector('#select-process-route').value;
      const subsidyLevel = container.querySelector('input[name="subsidy-level"]:checked')?.value;

      // 日付バリデーション
      if (dateStart && dateEnd && new Date(dateStart) > new Date(dateEnd)) {
        showError('開始日は終了日より前の日付を入力してください');
        return;
      }

      const allRows = await window.aivicApi.list(1);
      if (!allRows) {
        showError('データの取得に失敗しました');
        return;
      }

      const filteredRows = allRows.filter(row => {
        // キーワード検索
        if (keyword) {
          const searchText = `${row.申請タイトル || ''} ${row.申請内容 || ''}`.toLowerCase();
          if (!searchText.includes(keyword.toLowerCase())) return false;
        }

        // 文書種別
        if (documentType && row.申請種別 !== documentType) return false;

        // 承認状態
        if (approvalStatus && row.承認状態 !== approvalStatus) return false;

        // 申請日期間
        if (dateStart || dateEnd) {
          const rowDate = new Date(row.作成日時);
          if (dateStart && rowDate < new Date(dateStart)) return false;
          if (dateEnd && rowDate > new Date(dateEnd + 'T23:59:59')) return false;
        }

        // 申請者名
        if (applicant) {
          const applicantName = userMap.get(row.申請者ID) || '';
          if (!applicantName.includes(applicant)) return false;
        }

        // 承認者名
        if (approver) {
          const approverName = userMap.get(row.現在承認者ID) || '';
          if (!approverName.includes(approver)) return false;
        }

        // 処理ルート（簡易実装）
        if (processRoute) {
          // 実際の実装では処理ルートテーブルと結合が必要
          if (row.緊急フラグ && processRoute !== '緊急ルート') return false;
          if (!row.緊急フラグ && processRoute === '緊急ルート') return false;
        }

        // 補助金関連度
        if (subsidyLevel) {
          const rowSubsidyLevel = subsidyMap.get(row.補助金関連度ID) || '';
          if (rowSubsidyLevel !== subsidyLevel) return false;
        }

        return true;
      });

      renderRows(filteredRows);
    } catch (error) {
      console.error('Search error:', error);
      showError('検索処理中にエラーが発生しました');
    }
  }

  // 検索条件クリア
  function clearSearchConditions() {
    container.querySelector('#input-keyword').value = '';
    container.querySelector('#select-document-type').value = '';
    container.querySelector('#select-approval-status').value = '';
    container.querySelector('#input-date-start').value = '';
    container.querySelector('#input-date-end').value = '';
    container.querySelector('#input-applicant').value = '';
    container.querySelector('#input-approver').value = '';
    container.querySelector('#select-process-route').value = '';
    const subsidyRadios = container.querySelectorAll('input[name="subsidy-level"]');
    subsidyRadios.forEach(radio => radio.checked = false);

    // 全件表示
    if (tables[1] && tables[1].records) {
      renderRows(tables[1].records);
    }
  }

  // CSVエクスポート
  async function exportCSV() {
    try {
      const allRows = await window.aivicApi.list(1);
      if (!allRows || allRows.length === 0) {
        showError('エクスポートするデータがありません');
        return;
      }

      const headers = ['文書番号', '申請種別', '申請タイトル', '申請者', '申請日', '承認状態', '現在承認者', '補助金関連度'];
      const csvData = [headers.join(',')];

      allRows.forEach(row => {
        const applicantName = userMap.get(row.申請者ID) || '';
        const approverName = userMap.get(row.現在承認者ID) || '';
        const subsidyLevel = subsidyMap.get(row.補助金関連度ID) || '';

        const rowData = [
          `"${row.申請書類ID?.substring(0, 8) || ''}"`,
          `"${row.申請種別 || ''}"`,
          `"${row.申請タイトル || ''}"`,
          `"${applicantName}"`,
          `"${formatDate(row.作成日時)}"`,
          `"${row.承認状態 || ''}"`,
          `"${approverName}"`,
          `"${subsidyLevel}"`
        ];
        csvData.push(rowData.join(','));
      });

      const csvContent = '\uFEFF' + csvData.join('\n');
      const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
      const link = document.createElement('a');
      link.href = URL.createObjectURL(blob);
      link.download = `電子文書検索結果_${new Date().toISOString().slice(0, 10)}.csv`;
      link.click();
    } catch (error) {
      console.error('Export error:', error);
      showError('CSVエクスポート中にエラーが発生しました');
    }
  }

  // イベントリスナー
  container.querySelector('#btn-search').addEventListener('click', performSearch);
  container.querySelector('#btn-clear').addEventListener('click', clearSearchConditions);
  container.querySelector('#btn-export').addEventListener('click', exportCSV);

  // 文書番号リンククリック
  container.addEventListener('click', (e) => {
    const documentLink = e.target.closest('.document-link');
    if (documentLink) {
      e.preventDefault();
      const documentId = documentLink.dataset.id;
      // 申請書類確認画面へ遷移
      window.showScreen('scr-1779422434952');
    }
  });

  // Enterキーで検索
  container.addEventListener('keypress', (e) => {
    if (e.key === 'Enter') {
      performSearch();
    }
  });
}
